    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the primary mechanism of action of SSRIs?', '["Dopamine antagonism", "Selective inhibition of serotonin reuptake at the presynaptic neuron, increasing serotonin in the synaptic cleft", "Norepinephrine reuptake inhibition", "None"]', 1, 'The foundational mechanism of modern antidepressants. (Kaplan & Sadock)'),
    (v_topic_id, '2: How long does it typically take for an SSRI to achieve its full therapeutic antidepressant effect?', '["1 hour", "4 to 6 weeks", "1 year", "6 months"]', 1, 'Due to required neuroplastic changes (e.g., downregulation of presynaptic autoreceptors). (First Aid)'),
    (v_topic_id, '3: Which SSRI has the longest half-life?', '["Paroxetine", "Fluoxetine (has an active metabolite with a half-life of 1-2 weeks)", "Sertraline", "None"]', 1, 'Safe to stop abruptly without causing significant discontinuation syndrome. (MGH Pocket)'),
    (v_topic_id, '4: Which SSRI is notoriously teratogenic and associated with cardiovascular malformations (VSD) in the first trimester?', '["Sertraline", "Paroxetine", "Fluoxetine", "None"]', 1, 'Paroxetine is generally avoided in pregnancy (Category D). (Kaplan & Sadock)'),
    (v_topic_id, '5: Which SSRI is considered the safest and most well-studied in pregnancy and breastfeeding?', '["Paroxetine", "Sertraline", "Fluvoxamine", "None"]', 1, 'Sertraline is the go-to for perinatal depression. (First Aid)'),
    (v_topic_id, '6: Which SSRI is FDA-approved specifically for Obsessive-Compulsive Disorder (OCD) and has a very short half-life?', '["Citalopram", "Fluvoxamine", "Escitalopram", "None"]', 1, 'Fluvoxamine is heavily used in OCD and is a potent CYP inhibitor. (MGH Pocket)'),
    (v_topic_id, '7: What is the most significant black box warning for Citalopram?', '["Liver failure", "Dose-dependent QTc prolongation (max dose is usually 40mg/day, or 20mg/day in the elderly)", "Seizures", "None"]', 1, 'Escitalopram has less risk but still requires monitoring. (Kaplan & Sadock)'),
    (v_topic_id, '8: What is the most common reason patients stop taking SSRIs long-term?', '["Weight loss", "Sexual dysfunction (decreased libido, anorgasmia, delayed ejaculation)", "Hair loss", "None"]', 1, 'Affects up to 50% of patients and rarely resolves spontaneously. (First Aid)'),
    (v_topic_id, '9: Which two antidepressant classes lack sexual side effects?', '["SSRIs and TCAs", "Bupropion and Mirtazapine", "MAOIs and SNRIs", "None"]', 1, 'Often used as adjuncts or alternatives when SSRI-induced sexual dysfunction occurs. (MGH Pocket)'),
    (v_topic_id, '10: What is the mechanism of action of SNRIs (e.g., Venlafaxine, Duloxetine)?', '["Inhibit dopamine reuptake", "Inhibit reuptake of BOTH Serotonin and Norepinephrine", "GABA agonists", "None"]', 1, 'The addition of norepinephrine helps with pain and energy. (Kaplan & Sadock)'),
    (v_topic_id, '11: Which vital sign must be monitored closely in patients taking Venlafaxine?', '["Temperature", "Blood Pressure (can cause dose-dependent hypertension due to norepinephrine effects)", "Respiratory rate", "None"]', 1, 'Especially at doses above 150 mg/day. (First Aid)'),
    (v_topic_id, '12: Duloxetine (an SNRI) is particularly useful for depression that presents with what comorbid condition?', '["Obesity", "Neuropathic pain (e.g., diabetic neuropathy) or fibromyalgia", "Seizures", "None"]', 1, 'Norepinephrine reuptake inhibition modulates descending pain pathways. (MGH Pocket)'),
    (v_topic_id, '13: What is the mechanism of action of Bupropion?', '["Serotonin reuptake inhibitor", "Norepinephrine-Dopamine Reuptake Inhibitor (NDRI)", "MAOI", "None"]', 1, 'It lacks serotonergic activity, hence no sexual side effects or weight gain. (Kaplan & Sadock)'),
    (v_topic_id, '14: Bupropion is contraindicated in patients with what medical history?', '["Hypertension", "Seizure disorders, Anorexia Nervosa, or Bulimia Nervosa", "Diabetes", "None"]', 1, 'It lowers the seizure threshold. Eating disorders have electrolyte imbalances that already lower the threshold. (First Aid)'),
    (v_topic_id, '15: Besides depression, what is Bupropion FDA-approved to treat?', '["Schizophrenia", "Smoking Cessation (marketed as Zyban)", "Bipolar Mania", "None"]', 1, 'Dopamine effects help reduce nicotine cravings. (MGH Pocket)'),
    (v_topic_id, '16: What is the mechanism of action of Mirtazapine?', '["SSRI", "Alpha-2 antagonist (increases release of NE and 5-HT) and potent 5-HT2 and 5-HT3 antagonist", "Dopamine agonist", "None"]', 1, 'A unique mechanism among antidepressants. (Kaplan & Sadock)'),
    (v_topic_id, '17: What are the two most prominent side effects of Mirtazapine, which are often used therapeutically in elderly patients with depression?', '["Diarrhea and weight loss", "Sedation and significant weight gain/increased appetite", "Insomnia and anorexia", "None"]', 1, 'Due to its potent anti-histamine (H1) antagonism. (First Aid)'),
    (v_topic_id, '18: What is the primary use of Trazodone in modern psychiatry?', '["First-line for depression", "Used off-label at low doses as a non-habit-forming sleep aid (hypnotic)", "Treating mania", "None"]', 1, 'At high antidepressant doses, it is far too sedating. (MGH Pocket)'),
    (v_topic_id, '19: What is the rare but severe urologic emergency associated with Trazodone?', '["Kidney stones", "Priapism (sustained, painful erection)", "Renal failure", "None"]', 1, 'Due to alpha-1 adrenergic blockade. (Kaplan & Sadock)'),
    (v_topic_id, '20: How do Tricyclic Antidepressants (TCAs) work?', '["By blocking dopamine", "By inhibiting the reuptake of Norepinephrine and Serotonin (similar to SNRIs, but with many more off-target receptor blockades)", "None", "None"]', 1, 'They are "dirty" drugs that also block histamine, muscarinic, and alpha-1 receptors. (First Aid)'),
    (v_topic_id, '21: Which TCA is considered the gold standard treatment for severe Obsessive-Compulsive Disorder (OCD)?', '["Amitriptyline", "Clomipramine (it is the most highly serotonergic TCA)", "Imipramine", "None"]', 1, 'Used when SSRIs fail. (MGH Pocket)'),
    (v_topic_id, '22: Which TCA is specifically FDA-approved for Enuresis (bedwetting) in children?', '["Nortriptyline", "Imipramine", "Doxepin", "None"]', 1, 'Due to its strong anticholinergic (urinary retention) effects. (Kaplan & Sadock)'),
    (v_topic_id, '23: Which TCA is primarily used for neuropathic pain and migraine prophylaxis?', '["Clomipramine", "Amitriptyline", "Imipramine", "None"]', 1, 'A classic board question. (First Aid)'),
    (v_topic_id, '24: Why are TCAs rarely used as first-line antidepressants today?', '["They don''t work", "They are highly lethal in overdose (cardiotoxicity due to sodium channel blockade) and have severe anticholinergic side effects", "None", "None"]', 1, 'A 1-week supply can be fatal in overdose. (MGH Pocket)'),
    (v_topic_id, '25: What is the classic ECG finding in a TCA overdose?', '["ST elevation", "Widened QRS complex (which can rapidly degenerate into Torsades de pointes or V-fib)", "Peaked T waves", "None"]', 1, 'Treat with IV Sodium Bicarbonate. (Kaplan & Sadock)'),
    (v_topic_id, '26: What is the mechanism of action of Monoamine Oxidase Inhibitors (MAOIs)?', '["Block reuptake", "Irreversibly inhibit the MAO enzyme, preventing the degradation of serotonin, norepinephrine, and dopamine", "Increase release", "None"]', 1, 'The oldest class of antidepressants, highly effective but dangerous. (First Aid)'),
    (v_topic_id, '27: Name three classic non-selective MAOIs.', '["Fluoxetine, Sertraline, Paroxetine", "Phenelzine, Tranylcypromine, Isocarboxazid", "Lithium, Valproate, Lamotrigine", "None"]', 1, 'A fourth is Selegiline (MAO-B selective at low doses). (MGH Pocket)'),
    (v_topic_id, '28: What dietary restriction must patients on MAOIs strictly follow?', '["No sugar", "A Tyramine-free diet (no aged cheeses, cured meats, draft beer, red wine, fava beans)", "No salt", "None"]', 1, 'Tyramine acts as a false neurotransmitter and causes massive catecholamine release. (Kaplan & Sadock)'),
    (v_topic_id, '29: What happens if a patient on an MAOI eats a block of aged cheddar cheese?', '["Hypotension", "Hypertensive Crisis (severe headache, BP > 200/120, risk of stroke or MI)", "Sleepiness", "None"]', 1, 'This is a life-threatening medical emergency. (First Aid)'),
    (v_topic_id, '30: A patient is switching from Fluoxetine (an SSRI) to Phenelzine (an MAOI). How long must the "washout" period be to avoid Serotonin Syndrome?', '["2 days", "At least 5 weeks (due to Fluoxetine''s extremely long half-life)", "2 weeks", "None"]', 1, 'For most other SSRIs, the washout is 2 weeks. Fluoxetine is the exception. (MGH Pocket)'),
    (v_topic_id, '31: MAOIs are considered particularly effective for which subtype of depression?', '["Melancholic", "Atypical Depression (characterized by mood reactivity, leaden paralysis, hypersomnia, and hyperphagia)", "Psychotic", "None"]', 1, 'Though rarely used first-line due to side effects. (Kaplan & Sadock)'),
    (v_topic_id, '32: What is the fundamental mechanism of action of First-Generation (Typical) Antipsychotics?', '["Serotonin agonism", "Strong dopamine D2 receptor antagonism in the mesolimbic and nigrostriatal pathways", "GABA agonism", "None"]', 1, 'They are essentially pure dopamine blockers. (First Aid)'),
    (v_topic_id, '33: Name two HIGH-potency typical antipsychotics.', '["Chlorpromazine, Thioridazine", "Haloperidol, Fluphenazine", "Clozapine, Quetiapine", "None"]', 1, 'High potency = high D2 affinity = high risk of Extrapyramidal Symptoms (EPS). (MGH Pocket)'),
    (v_topic_id, '34: Name two LOW-potency typical antipsychotics.', '["Haloperidol, Fluphenazine", "Chlorpromazine, Thioridazine", "Risperidone, Olanzapine", "None"]', 1, 'Low potency = lower D2 affinity but high anticholinergic/antihistamine side effects. (Kaplan & Sadock)'),
    (v_topic_id, '35: What unique side effect is associated with Chlorpromazine?', '["Retinal pigmentation", "Corneal deposits and blue-gray skin discoloration", "Heart failure", "None"]', 1, '"Chlorpromazine = Corneal." (First Aid)'),
    (v_topic_id, '36: What unique side effect is associated with Thioridazine?', '["Corneal deposits", "Irreversible retinal pigmentation (retinitis pigmentosa) leading to blindness", "Kidney stones", "None"]', 1, 'It also has a very high risk of QTc prolongation. (MGH Pocket)'),
    (v_topic_id, '37: Blocking dopamine in the Nigrostriatal pathway causes what side effects?', '["Dry mouth", "Extrapyramidal Symptoms (EPS) like dystonia, parkinsonism, and akathisia", "Galactorrhea", "None"]', 1, 'This pathway controls voluntary movement. (Kaplan & Sadock)'),
    (v_topic_id, '38: Blocking dopamine in the Tuberoinfundibular pathway causes what side effects?', '["Movement disorders", "Hyperprolactinemia (leading to galactorrhea, amenorrhea, gynecomastia, and sexual dysfunction)", "Sedation", "None"]', 1, 'Dopamine normally inhibits prolactin release. (First Aid)'),
    (v_topic_id, '39: Blocking dopamine in the Mesolimbic pathway achieves what clinical effect?', '["Worsens negative symptoms", "Reduces POSITIVE symptoms of schizophrenia (hallucinations, delusions)", "Causes sedation", "None"]', 1, 'This is the desired therapeutic target for antipsychotics. (MGH Pocket)'),
    (v_topic_id, '40: Blocking dopamine in the Mesocortical pathway causes what side effect?', '["Reduces positive symptoms", "Can worsen NEGATIVE symptoms (apathy, alogia) and cognitive deficits", "Causes lactation", "None"]', 1, 'First-generation antipsychotics often make negative symptoms worse. (Kaplan & Sadock)'),
    (v_topic_id, '41: What is the timeline for Acute Dystonia after starting an antipsychotic?', '["Months", "Hours to Days", "Years", "Weeks"]', 1, 'It is the earliest EPS to appear. Treat with Benztropine or Diphenhydramine. (First Aid)'),
    (v_topic_id, '42: What is the timeline for Akathisia after starting an antipsychotic?', '["Years", "Days to Weeks", "Hours", "Decades"]', 1, 'Treat with Propranolol (Beta-blockers). (MGH Pocket)'),
    (v_topic_id, '43: What is the timeline for Antipsychotic-Induced Parkinsonism?', '["Hours", "Weeks to Months", "Years", "None"]', 1, 'Treat with Amantadine or Benztropine. (Kaplan & Sadock)'),
    (v_topic_id, '44: What is the timeline for Tardive Dyskinesia?', '["Hours", "Months to Years of chronic use", "Days", "None"]', 1, 'Often irreversible. Prevent by using lowest effective dose or atypicals. (First Aid)'),
    (v_topic_id, '45: How do Second-Generation (Atypical) Antipsychotics differ from Typical Antipsychotics in their mechanism?",', '["They don''t", "They antagonize BOTH Dopamine D2 receptors AND Serotonin 5-HT2A receptors", "They only block serotonin", "None"]', 1, '5-HT2A blockade increases dopamine release in the striatum, reducing the risk of EPS. (MGH Pocket)'),
    (v_topic_id, '46: What is the primary advantage of Atypical Antipsychotics over Typical Antipsychotics?",', '["Lower cost", "Significantly lower risk of Extrapyramidal Symptoms (EPS) and Tardive Dyskinesia, and possibly better efficacy for negative symptoms", "No weight gain", "None"]', 1, 'They are the first-line treatment for schizophrenia. (Kaplan & Sadock)'),
    (v_topic_id, '47: What is the primary DISADVANTAGE of Atypical Antipsychotics?",', '["High risk of EPS", "High risk of Metabolic Syndrome (significant weight gain, hyperlipidemia, hyperglycemia, new-onset diabetes)", "They don''t treat hallucinations", "None"]', 1, 'Metabolic monitoring is mandatory. (First Aid)'),
    (v_topic_id, '48: Which two Atypical Antipsychotics carry the HIGHEST risk of Metabolic Syndrome?",', '["Aripiprazole and Ziprasidone", "Olanzapine and Clozapine", "Risperidone and Paliperidone", "None"]', 1, 'Patients can gain 50+ lbs rapidly. (MGH Pocket)'),
    (v_topic_id, '49: Which two Atypical Antipsychotics are the most "weight-neutral" (lowest risk of metabolic syndrome)?",', '["Olanzapine and Clozapine", "Aripiprazole and Ziprasidone", "Quetiapine and Risperidone", "None"]', 1, 'Lurasidone is also generally weight-neutral. (Kaplan & Sadock)'),
    (v_topic_id, '50: Which Atypical Antipsychotic is most famous for causing Hyperprolactinemia (galactorrhea, amenorrhea)?",', '["Quetiapine", "Risperidone (and its metabolite Paliperidone)", "Aripiprazole", "None"]', 1, 'It has the tightest D2 binding among the atypicals. (First Aid)'),
    (v_topic_id, '51: Which Atypical Antipsychotic is most sedating and frequently used off-label for sleep?",', '["Aripiprazole", "Quetiapine (Seroquel)", "Ziprasidone", "None"]', 1, 'Strong H1 (histamine) antagonism. (MGH Pocket)'),
    (v_topic_id, '52: What is unique about the mechanism of Aripiprazole?",', '["It is a pure antagonist", "It is a PARTIAL agonist at the D2 receptor (rather than a full antagonist)", "It blocks GABA", "None"]', 1, 'Acts as an antagonist in hyperdopaminergic areas, and an agonist in hypodopaminergic areas. (Kaplan & Sadock)'),
    (v_topic_id, '53: Which Atypical Antipsychotic must be taken with food (at least 350-500 calories) for proper absorption?",', '["Risperidone", "Ziprasidone (Geodon) and Lurasidone (Latuda)", "Olanzapine", "None"]', 1, 'Without food, absorption drops by 50%. (First Aid)'),
    (v_topic_id, '54: Which Atypical Antipsychotic carries the highest risk of QTc prolongation?",', '["Aripiprazole", "Ziprasidone", "Lurasidone", "None"]', 1, 'Always check an ECG before starting. (MGH Pocket)'),
    (v_topic_id, '55: When is Clozapine indicated?",', '["First line for all psychosis", "Only for TREATMENT-RESISTANT Schizophrenia (failed at least 2 other antipsychotics) or Schizophrenia with severe suicidality", "None", "None"]', 1, 'It is the most effective antipsychotic but has the most dangerous side effect profile. (Kaplan & Sadock)'),
    (v_topic_id, '56: What are the 5 major black-box warnings for Clozapine?",', '["None", "Agranulocytosis, Seizures, Myocarditis, Orthostatic Hypotension/Syncope, and increased mortality in elderly patients with dementia", "None", "None"]', 1, 'A high-yield board question. (First Aid)'),
    (v_topic_id, '57: What mandatory monitoring program exists for Clozapine?",', '["None", "The Clozapine REMS program, requiring strictly scheduled Absolute Neutrophil Count (ANC) blood draws to prevent fatal Agranulocytosis", "None", "None"]', 1, 'No blood, no drug. (MGH Pocket)'),
    (v_topic_id, '58: What highly annoying, non-lethal side effect of Clozapine often impairs patient compliance?",', '["Dry mouth", "Severe sialorrhea (drooling, especially at night)", "Weight loss", "None"]', 1, 'Paradoxical because Clozapine is highly anticholinergic, yet causes drooling (due to M4 agonism). (Kaplan & Sadock)'),
    (v_topic_id, '59: What is the therapeutic blood level range for Lithium?",', '["0.1 - 0.5 mEq/L", "0.6 - 1.2 mEq/L", "1.5 - 2.5 mEq/L", "None"]', 1, 'Levels > 1.5 mEq/L indicate toxicity. (First Aid)'),
    (v_topic_id, '60: How is Lithium metabolized?",', '["By the liver (CYP450)", "It is NOT metabolized; it is an elemental ion entirely excreted unchanged by the Kidneys", "By the lungs", "None"]', 1, 'Therefore, kidney function (BUN/Cr) must be strictly monitored. (MGH Pocket)'),
    (v_topic_id, '61: What are the primary baseline labs required before starting a patient on Lithium?",', '["None", "BUN/Creatinine (renal function), TSH (thyroid function), and an ECG (especially in patients > 40) and pregnancy test", "Liver function tests", "None"]', 1, 'Lithium is toxic to the kidneys and thyroid. (Kaplan & Sadock)'),
    (v_topic_id, '62: What is the classic fine neurological sign of Lithium use (even at therapeutic levels)?",', '["Seizures", "A fine postural hand tremor", "Nystagmus", "None"]', 1, 'Can be treated with Propranolol. A COARSE tremor indicates toxicity. (First Aid)'),
    (v_topic_id, '63: What cardiac rhythm abnormality can Lithium commonly cause?",', '["V-fib", "T wave flattening or inversion, and occasionally sick sinus syndrome (bradycardia)", "ST elevation", "None"]', 1, 'Usually benign, but monitor closely. (MGH Pocket)'),
    (v_topic_id, '64: What is the mechanism of action of Valproic Acid (Depakote)?",', '["Blocks serotonin", "Increases brain GABA levels (by inhibiting GABA transaminase) and blocks voltage-gated sodium channels", "Increases dopamine", "None"]', 1, 'Highly effective for acute mania. (Kaplan & Sadock)'),
    (v_topic_id, '65: What are the three most severe (black box) warnings for Valproic Acid?",', '["None", "Hepatotoxicity, Pancreatitis, and severe Teratogenicity (Neural Tube Defects)", "Kidney failure", "None"]', 1, 'Check LFTs, Lipase, and pregnancy test. (First Aid)'),
    (v_topic_id, '66: Which mood stabilizer is most notorious for causing significant weight gain and alopecia (hair loss)?",', '["Lamotrigine", "Valproic Acid", "Carbamazepine", "None"]', 1, 'It also frequently causes PCOS in women. (MGH Pocket)'),
    (v_topic_id, '67: What is the primary use of Lamotrigine in Bipolar Disorder?",', '["Treating acute mania", "Maintenance therapy, specifically for preventing the DEPRESSIVE episodes of Bipolar Disorder", "Rapid tranquilization", "None"]', 1, 'It is useless for acute mania. (Kaplan & Sadock)'),
    (v_topic_id, '68: What is the mechanism of action of Carbamazepine?",', '["Increases Serotonin", "Blocks voltage-gated sodium channels", "Blocks dopamine", "None"]', 1, 'Effective for Bipolar Mania and Trigeminal Neuralgia. (First Aid)'),
    (v_topic_id, '69: Carbamazepine is a potent CYP450 AUTO-inducer. What does this mean?",', '["It stops its own absorption", "It induces the enzymes that metabolize it, meaning its half-life decreases over time, requiring dosage increases after a few weeks", "None", "None"]', 1, 'It also induces the metabolism of almost everything else (e.g., oral contraceptives will fail). (MGH Pocket)'),
    (v_topic_id, '70: What severe cutaneous adverse reaction is associated with Carbamazepine, especially in patients with the HLA-B*1502 allele (common in Asian populations)?",', '["Acne", "Stevens-Johnson Syndrome (SJS)", "Psoriasis", "None"]', 1, 'Genetic screening is recommended for at-risk populations before starting. (Kaplan & Sadock)'),
    (v_topic_id, '71: What is the mechanism of action of Benzodiazepines?",', '["They are pure GABA agonists", "They bind to the GABA-A receptor and increase the FREQUENCY of chloride channel opening, enhancing the inhibitory effect of GABA", "None", "None"]', 1, '"Frenzodiazepines" increase Frequency. (First Aid)'),
    (v_topic_id, '72: What is the mechanism of action of Barbiturates?",', '["Increase GABA frequency", "They bind to the GABA-A receptor and increase the DURATION of chloride channel opening. At high doses, they can open the channel independently of GABA.", "None", "None"]', 1, '"BarbiDURATES" increase Duration. This makes them much more lethal in overdose than benzos. (MGH Pocket)'),
    (v_topic_id, '73: Which Benzodiazepines bypass liver CYP450 metabolism and are preferred in elderly patients or those with severe liver disease?",', '["Diazepam and Clonazepam", "Lorazepam, Oxazepam, and Temazepam (the ''''LOT'''' benzos)", "Alprazolam", "None"]', 1, 'They are metabolized solely by Phase II glucuronidation. (Kaplan & Sadock)'),
    (v_topic_id, '74: Which Benzodiazepine is notorious for having a very short half-life and causing severe rebound anxiety and intense physical dependence?",', '["Diazepam", "Alprazolam (Xanax)", "Clonazepam", "None"]', 1, 'Often avoided by psychiatrists due to addiction potential. (First Aid)'),
    (v_topic_id, '75: Which Benzodiazepine has the longest half-life and active metabolites, making it ideal for alcohol withdrawal tapers?",', '["Alprazolam", "Diazepam (Valium) or Chlordiazepoxide (Librium)", "Lorazepam", "None"]', 1, 'Self-tapering effects smooth out withdrawal. (MGH Pocket)'),
    (v_topic_id, '76: What is Buspirone used for, and what is its mechanism?",', '["Acute panic", "Used for Generalized Anxiety Disorder (GAD). It is a Serotonin 5-HT1A partial agonist.", "Sleep", "None"]', 1, 'It is non-sedating, non-addictive, but takes 2-4 weeks to work. It is useless for acute panic. (Kaplan & Sadock)'),
    (v_topic_id, '77: What are the "Z-drugs" (Zolpidem, Zaleplon, Eszopiclone)?",', '["Antidepressants", "Non-benzodiazepine hypnotics that bind to the Benzodiazepine-1 (BZ1) receptor subtype to induce sleep", "Antipsychotics", "None"]', 1, 'They have less effect on sleep architecture but can cause sleepwalking/amnesia. (First Aid)'),
    (v_topic_id, '78: What is the mechanism of action of Suvorexant?",', '["GABA agonist", "Orexin receptor antagonist", "Serotonin antagonist", "None"]', 1, 'Blocks the "wakefulness" neuropeptide (orexin), inducing sleep. Contraindicated in narcolepsy. (MGH Pocket)'),
    (v_topic_id, '79: What is the mechanism of action of Ramelteon?",', '["Orexin antagonist", "Melatonin MT1 and MT2 receptor agonist", "GABA agonist", "None"]', 1, 'Used for sleep onset insomnia. Non-habit forming. (Kaplan & Sadock)'),
    (v_topic_id, '80: What is the mechanism of action of Stimulants (Amphetamines and Methylphenidate)?",', '["Block GABA", "Increase the release and block the reuptake of Dopamine and Norepinephrine in the prefrontal cortex and striatum", "Increase Serotonin", "None"]', 1, 'The absolute first-line treatment for ADHD. (First Aid)'),
    (v_topic_id, '81: What are the most common side effects of Stimulants in children?",', '["Weight gain and sleepiness", "Appetite suppression, weight loss, insomnia, and tics", "Liver failure", "None"]', 1, 'Growth velocity must be monitored. (MGH Pocket)'),
    (v_topic_id, '82: What is Atomoxetine?",', '["A stimulant", "A non-stimulant Selective Norepinephrine Reuptake Inhibitor (SNRI) used for ADHD", "An antipsychotic", "None"]', 1, 'Used when stimulants fail, cause intolerable side effects (tics), or in patients with substance abuse history. (Kaplan & Sadock)'),
    (v_topic_id, '83: What is the mechanism of action of Guanfacine and Clonidine in ADHD?",', '["Alpha-1 antagonists", "Alpha-2 adrenergic AGONISTS", "Beta blockers", "None"]', 1, 'They enhance prefrontal cortical functioning. Very useful for the hyperactivity/impulsivity components and for tic disorders. (First Aid)'),
    (v_topic_id, '84: A patient taking Haloperidol develops severe muscle stiffness and a fever of 104 F. What is the pharmacological treatment?",', '["More Haloperidol", "Dantrolene (muscle relaxant) or Bromocriptine/Amantadine (dopamine agonists)", "Lithium", "None"]', 1, 'Treatment for Neuroleptic Malignant Syndrome. (MGH Pocket)'),
    (v_topic_id, '85: A patient taking Fluoxetine and sumatriptan develops tremor, hyperreflexia, and shivering. What is the pharmacological treatment?",', '["Naloxone", "Cyproheptadine (5-HT2 receptor antagonist)", "Flumazenil", "None"]', 1, 'Treatment for Serotonin Syndrome. (Kaplan & Sadock)'),
    (v_topic_id, '86: What is the antidote for Benzodiazepine overdose?",', '["Naloxone", "Flumazenil (competitive antagonist at the GABA-A receptor)", "Fomepizole", "None"]', 1, 'Use with extreme caution due to seizure risk. (First Aid)'),
    (v_topic_id, '87: What is the antidote for Opioid overdose?",', '["Flumazenil", "Naloxone (competitive opioid receptor antagonist)", "Methadone", "None"]', 1, 'Life-saving in the field. (MGH Pocket)'),
    (v_topic_id, '88: How does Methadone work for Opioid Use Disorder?",', '["It blocks opioids", "It is a long-acting FULL mu-opioid agonist that reduces cravings and prevents withdrawal without causing a high", "None", "None"]', 1, 'Must be administered daily in a strictly regulated clinic. Can prolong QTc. (Kaplan & Sadock)'),
    (v_topic_id, '89: How does Buprenorphine work for Opioid Use Disorder?",', '["It is a full agonist", "It is a PARTIAL mu-opioid agonist. It binds with extremely high affinity (displacing other opioids) but has low intrinsic activity.", "None", "None"]', 1, 'Can be prescribed in an outpatient office setting. Has a ceiling effect for respiratory depression. (First Aid)'),
    (v_topic_id, '90: Why is Buprenorphine often combined with Naloxone (Suboxone)?",', '["To make it taste better", "To prevent IV abuse. If taken orally/sublingually as prescribed, the Naloxone is destroyed by first-pass metabolism. If injected, the Naloxone is 100% bioavailable and triggers immediate severe withdrawal.", "None", "None"]', 1, 'A brilliant pharmacological safety mechanism. (MGH Pocket)'),
    (v_topic_id, '91: How does Naltrexone work for Opioid Use Disorder?",', '["Partial agonist", "It is a competitive opioid ANTAGONIST. It blocks the effects of any illicit opioids.", "Agonist", "None"]', 1, 'The patient MUST be fully detoxed (opioid-free for 7-10 days) before starting, otherwise it will precipitate severe withdrawal. (Kaplan & Sadock)'),
    (v_topic_id, '92: How does Naltrexone work for Alcohol Use Disorder?",', '["It makes them vomit", "It blocks mu-opioid receptors, which reduces the euphoric reward/craving associated with drinking alcohol", "It is a placebo", "None"]', 1, 'First-line medication for alcohol use disorder. (First Aid)'),
    (v_topic_id, '93: How does Acamprosate work for Alcohol Use Disorder?",', '["Blocks alcohol absorption", "Modulates glutamate neurotransmission (NMDA receptor antagonist), reducing the hyper-excitability of chronic alcohol withdrawal/cravings", "Causes vomiting", "None"]', 1, 'Safe in liver disease (it is renally excreted). (MGH Pocket)'),
    (v_topic_id, '94: How does Disulfiram (Antabuse) work for Alcohol Use Disorder?",', '["Reduces cravings", "It irreversibly inhibits Aldehyde Dehydrogenase. If the patient drinks alcohol, acetaldehyde builds up, causing severe nausea, vomiting, flushing, and palpitations.", "Blocks receptors", "None"]', 1, 'Classical conditioning (aversive therapy). Second-line due to poor compliance. (Kaplan & Sadock)'),
    (v_topic_id, '95: A patient with a history of severe liver disease (cirrhosis) wants medication for Alcohol Use Disorder. Which medication is preferred?",', '["Naltrexone", "Acamprosate (it is metabolized and excreted entirely by the kidneys)", "Disulfiram", "None"]', 1, 'Naltrexone can be hepatotoxic. (First Aid)'),
    (v_topic_id, '96: Varenicline (Chantix) is used for smoking cessation. What is its mechanism?",', '["Nicotine antagonist", "Partial agonist at the alpha-4 beta-2 nicotinic acetylcholine receptor", "Dopamine antagonist", "None"]', 1, 'Reduces cravings and blunts the rewarding effects if they do smoke. (MGH Pocket)'),
    (v_topic_id, '97: Which SSRI has the highest risk of causing GI side effects (diarrhea/nausea)?",', '["Paroxetine", "Sertraline (''''Squirt-raline'''')", "Fluoxetine", "None"]', 1, 'Often self-resolves after a few weeks. (Kaplan & Sadock)'),
    (v_topic_id, '98: A patient taking Venlafaxine for 2 years stops taking it because they went on vacation and forgot their pills. They arrive in the ER with severe dizziness, "electric shock" sensations in their brain, nausea, and crying spells. Diagnosis?",', '["Serotonin Syndrome", "Antidepressant Discontinuation Syndrome", "Stroke", "None"]', 1, 'Venlafaxine has a very short half-life and causes intense withdrawal if stopped abruptly. (First Aid)'),
    (v_topic_id, '99: Which antidepressant is classically associated with lowering the seizure threshold, especially in patients with bulimia?",', '["Fluoxetine", "Bupropion", "Mirtazapine", "None"]', 1, 'An absolute contraindication. (MGH Pocket)'),
    (v_topic_id, '100: A patient with dementia is agitated. The doctor orders Haloperidol. Why must the dose be extremely low?",', '["It causes diarrhea", "Elderly patients are highly sensitive to EPS, and all antipsychotics carry a black-box warning for increased mortality (cardiac events/infection) in dementia-related psychosis", "None", "None"]', 1, '"Start low and go slow." (Kaplan & Sadock)'),
    (v_topic_id, '101: Which SSRI has the highest risk of causing anticholinergic side effects (dry mouth, constipation)?', '["Fluoxetine", "Paroxetine", "Sertraline", "None"]', 1, 'Paroxetine is the most anticholinergic of the SSRIs. (MGH Pocket)'),
    (v_topic_id, '102: Which class of antidepressants is contraindicated in a patient with a history of narrow-angle glaucoma or urinary retention?', '["SSRIs", "Tricyclic Antidepressants (TCAs)", "SNRIs", "None"]', 1, 'Due to their potent anticholinergic properties. (First Aid)'),
    (v_topic_id, '103: A patient on Lithium presents with a fine resting tremor. What medication can be used to treat this side effect without stopping the Lithium?', '["Haloperidol", "Propranolol (a beta-blocker)", "Benztropine", "None"]', 1, 'Beta-blockers effectively dampen the peripheral tremor. (Kaplan & Sadock)'),
    (v_topic_id, '104: A patient taking Valproic acid (Depakote) for bipolar disorder wants to become pregnant. What should you advise?', '["It is perfectly safe", "Valproic acid is highly teratogenic (neural tube defects). She should be transitioned to a safer mood stabilizer (e.g., Lamotrigine) BEFORE conceiving.", "Take extra vitamin C", "None"]', 1, 'Never keep a woman of childbearing age on Valproate without a strong clinical reason and contraception. (MGH Pocket)'),
    (v_topic_id, '105: What is the mechanism of action of Topiramate (Topamax)?', '["Dopamine antagonist", "Blocks sodium channels and enhances GABA activity", "Serotonin agonist", "None"]', 1, 'Often used off-label in psychiatry for binge eating disorder and weight loss. (First Aid)'),
    (v_topic_id, '106: What are two common side effects of Topiramate that limit its use?', '["Weight gain and sedation", "Cognitive dulling (''''Dopamax'''') and kidney stones", "Hyperactivity and diarrhea", "None"]', 1, 'Patients often complain of word-finding difficulties. (Kaplan & Sadock)'),
    (v_topic_id, '107: A patient taking Mirtazapine complains of extreme sedation. What happens to the sedative effect if you INCREASE the dose from 15mg to 45mg?', '["They will sleep forever", "The sedation DECREASES. At higher doses, increased noradrenergic transmission counteracts the antihistamine-induced sedation.", "None", "None"]', 1, 'A paradoxical but clinically important phenomenon. (MGH Pocket)'),
    (v_topic_id, '108: Which medication is an NDRI (Norepinephrine-Dopamine Reuptake Inhibitor)?', '["Venlafaxine", "Bupropion", "Mirtazapine", "None"]', 1, 'The only antidepressant that works primarily on dopamine. (First Aid)'),
    (v_topic_id, '109: A patient with ADHD is prescribed Methylphenidate. What schedule of controlled substance is this?', '["Schedule I", "Schedule II (high potential for abuse)", "Schedule IV", "None"]', 1, 'Requires strict prescribing protocols and no refills without a new prescription. (Kaplan & Sadock)'),
    (v_topic_id, '110: A patient with Bipolar Disorder is acutely manic. The resident starts them on Sertraline to help with their mood. What is the risk?', '["It will cause sleep", "Antidepressant monotherapy can precipitate a severe manic episode or rapid cycling in bipolar patients", "It cures them", "None"]', 1, 'Never use an antidepressant WITHOUT a mood stabilizer in Bipolar I. (MGH Pocket)'),
    (v_topic_id, '111: Which mood stabilizer has been shown to reduce the risk of suicide in patients with Bipolar Disorder?', '["Valproate", "Lithium", "Carbamazepine", "None"]', 1, 'Along with Clozapine in Schizophrenia, it is one of the few drugs with proven anti-suicide properties. (First Aid)'),
    (v_topic_id, '112: A patient is taking Ziprasidone (Geodon) for Schizophrenia. The nurse notices the patient is taking it with a glass of water on an empty stomach. What is the concern?', '["It causes ulcers", "Ziprasidone MUST be taken with at least 500 calories of food, or its absorption is reduced by 50%", "None", "None"]', 1, 'Lurasidone (Latuda) has the same requirement (350 calories). (Kaplan & Sadock)'),
    (v_topic_id, '113: Which atypical antipsychotic comes in a sublingual formulation that should NOT be swallowed, and the patient must not eat or drink for 10 minutes after?', '["Olanzapine", "Asenapine (Saphris)", "Quetiapine", "None"]', 1, 'If swallowed, the bioavailability is near zero due to first-pass metabolism. (MGH Pocket)'),
    (v_topic_id, '114: A patient taking Clozapine has an Absolute Neutrophil Count (ANC) of 500/uL. What must the doctor do?', '["Lower the dose", "Immediately stop the Clozapine. This is severe neutropenia (agranulocytosis).", "Give an antibiotic", "None"]', 1, 'A life-threatening hematologic emergency. (First Aid)'),
    (v_topic_id, '115: What is "Neuroleptic Malignant Syndrome" (NMS)?', '["An allergy to SSRIs", "A life-threatening neurological emergency caused by dopamine antagonism (antipsychotics), characterized by fever, severe muscle rigidity (lead-pipe), autonomic instability, and altered mental status", "A type of seizure", "None"]', 1, 'A true medical emergency with high mortality. (First Aid)'),
    (v_topic_id, '116: Which laboratory findings are classically markedly elevated in NMS?', '["Troponin", "Creatine Kinase (CK/CPK) and White Blood Cell count (Leukocytosis)", "Amylase", "None"]', 1, 'Due to severe muscle breakdown (rhabdomyolysis) from the rigidity. (MGH Pocket)'),
    (v_topic_id, '117: What is the most important initial step in treating Neuroleptic Malignant Syndrome?', '["Give more antipsychotics", "Immediately DISCONTINUE the offending antipsychotic agent and provide aggressive supportive care (IV fluids, cooling blankets)", "Give antibiotics", "None"]', 1, 'Supportive care is paramount. (Kaplan & Sadock)'),
    (v_topic_id, '118: What pharmacological agents can be used to treat severe Neuroleptic Malignant Syndrome?', '["Haloperidol", "Dantrolene (a direct muscle relaxant) or Bromocriptine/Amantadine (dopamine agonists)", "Lithium", "None"]', 1, 'You need to relax the muscles and override the dopamine blockade. (First Aid)'),
    (v_topic_id, '119: What is "Serotonin Syndrome"?', '["Depression", "A life-threatening condition caused by excessive serotonergic activity, characterized by altered mental status, autonomic instability, and neuromuscular hyperactivity (e.g., hyperreflexia, clonus)", "Mania", "None"]', 1, 'Often caused by combining SSRIs with MAOIs, TCAs, or triptans. (MGH Pocket)'),
    (v_topic_id, '120: How do the physical exam findings of Serotonin Syndrome differ from NMS?', '["They are identical", "NMS has ''''lead-pipe'''' rigidity and hyporeflexia. Serotonin Syndrome has hyperreflexia, myoclonus, and ocular clonus.", "None", "None"]', 1, 'Reflexes are the key differentiating factor on the exam. (Kaplan & Sadock)'),
    (v_topic_id, '121: What is the antidote for severe Serotonin Syndrome?', '["Flumazenil", "Cyproheptadine (a 5-HT2 receptor antagonist)", "Naloxone", "None"]', 1, 'Blocks the serotonin receptors. (First Aid)'),
    (v_topic_id, '122: A patient presents with acute dystonia (e.g., torticollis, oculogyric crisis) shortly after receiving IM Haloperidol. What is the treatment?', '["More Haloperidol", "IM Benztropine or IM Diphenhydramine (anticholinergics)", "Epinephrine", "None"]', 1, 'Restores the dopamine-acetylcholine balance in the basal ganglia. (MGH Pocket)'),
    (v_topic_id, '123: What is a "Tardive Dyskinesia" emergency?', '["It is not an emergency", "It is usually a chronic, irreversible condition (lip smacking, choreoathetoid movements) caused by long-term antipsychotic use, but severe cases can impair breathing/swallowing", "None", "None"]', 1, 'Treat with VMAT2 inhibitors (Valbenazine) and stop the offending drug if possible. (Kaplan & Sadock)'),
    (v_topic_id, '124: A patient taking Lithium presents with coarse tremors, ataxia, vomiting, and confusion. What is the likely diagnosis?', '["Alcohol withdrawal", "Lithium Toxicity", "NMS", "None"]', 1, 'Lithium has a very narrow therapeutic index. (First Aid)'),
    (v_topic_id, '125: What is the treatment for severe Lithium toxicity (levels > 2.5 mEq/L with neurological symptoms or renal failure)?', '["Activated charcoal", "Hemodialysis", "IV Calcium", "None"]', 1, 'Lithium is a small ion that is easily dialyzable. (MGH Pocket)'),
    (v_topic_id, '126: A patient who ingested an unknown amount of Tricyclic Antidepressants (TCAs) presents with tachycardia, dilated pupils, and dry skin. What is the most dreaded complication?', '["Liver failure", "Fatal cardiac arrhythmias (widened QRS leading to Torsades/V-fib) and intractable seizures", "Kidney failure", "None"]', 1, 'TCAs block cardiac sodium channels. (Kaplan & Sadock)'),
    (v_topic_id, '127: What is the treatment for TCA cardiotoxicity (widened QRS complex)?', '["Amiodarone", "IV Sodium Bicarbonate", "Beta blockers", "None"]', 1, 'Bicarbonate overcomes the sodium channel blockade and alkalinizes the blood, reducing drug binding. (First Aid)'),
    (v_topic_id, '128: A patient taking Tranylcypromine (an MAOI) presents with a severe headache, flushing, and a blood pressure of 220/120 after eating aged cheese and drinking red wine. Diagnosis?', '["Migraine", "Hypertensive Crisis (Tyramine reaction)", "Stroke", "None"]', 1, 'Tyramine acts as a sympathomimetic when MAO is blocked. (MGH Pocket)'),
    (v_topic_id, '129: What is the treatment for an MAOI-induced hypertensive crisis?', '["Beta blockers only", "Phentolamine (alpha-1 antagonist) or Nitroprusside", "Epinephrine", "None"]', 1, 'You must block the massive alpha-adrenergic vasoconstriction. (Kaplan & Sadock)'),
    (v_topic_id, '130: Which medication class is notorious for causing weight gain, sedation, and dry mouth by blocking Histamine (H1) and Muscarinic (M1) receptors?', '["Stimulants", "TCAs and low-potency typical antipsychotics (e.g., Chlorpromazine)", "SSRIs", "None"]', 1, 'The "dirty" side effect profile. (First Aid)'),
    (v_topic_id, '131: A patient on an SSRI wants to take a triptan for their migraine. What is the theoretical risk?', '["Hypertension", "Serotonin Syndrome", "Seizures", "None"]', 1, 'Triptans are 5-HT1B/1D agonists. The clinical risk is low but routinely flagged by pharmacies. (MGH Pocket)'),
    (v_topic_id, '132: What happens if you give an MAOI and a TCA together?', '["Nothing", "High risk of Serotonin Syndrome and Hypertensive Crisis. They should almost never be combined.", "None", "None"]', 1, 'Requires expert psychopharmacological management if attempted. (Kaplan & Sadock)'),
    (v_topic_id, '133: A patient takes Selegiline. At low doses (e.g., the transdermal patch 6mg/day), does the patient need to follow a Tyramine-free diet?', '["Yes", "No. At low doses, Selegiline is selective for MAO-B (which breaks down dopamine), sparing MAO-A in the gut.", "None", "None"]', 1, 'At high doses, it loses selectivity and dietary restrictions apply. (First Aid)'),
    (v_topic_id, '134: A patient taking Lithium develops polyuria (excessive urination) and polydipsia (excessive thirst). Their urine is very dilute. What is the diagnosis?', '["Diabetes Mellitus", "Nephrogenic Diabetes Insipidus (Lithium makes the kidney collecting ducts insensitive to ADH)", "UTI", "None"]', 1, 'Treat by discontinuing Lithium if possible, or using Amiloride. (MGH Pocket)'),
    (v_topic_id, '135: What happens to the Lithium level if a patient takes a Thiazide diuretic?', '["It drops", "It INCREASES significantly, leading to toxicity. Thiazides deplete sodium, causing the kidneys to reabsorb more sodium (and Lithium) in the proximal tubule.", "None", "None"]', 1, 'A very common and dangerous drug-drug interaction. (Kaplan & Sadock)'),
    (v_topic_id, '136: A pregnant patient takes Lithium. What is the specific congenital anomaly associated with this exposure?",', '["Spina bifida", "Ebstein''s Anomaly (downward displacement of the tricuspid valve into the right ventricle)", "Cleft palate", "None"]', 1, 'The absolute risk is very small (1 in 1000), but relative risk is increased. (First Aid)'),
    (v_topic_id, '137: Which mood stabilizer is most strongly associated with Neural Tube Defects (e.g., Spina Bifida)?",', '["Lithium", "Valproic Acid (Depakote)", "Lamotrigine", "None"]', 1, 'Women of childbearing age must take high-dose folate if on Valproate. (MGH Pocket)'),
    (v_topic_id, '138: A patient starts Lamotrigine and develops a rapidly spreading, painful rash with mucosal involvement and skin peeling. Diagnosis?",', '["Acne", "Stevens-Johnson Syndrome (SJS) or Toxic Epidermal Necrolysis (TEN)", "Psoriasis", "None"]', 1, 'A dermatologic emergency. Stop the drug immediately. (Kaplan & Sadock)'),
    (v_topic_id, '139: How do you prevent Lamotrigine-induced SJS?",', '["Take with food", "Slow dose titration over several weeks", "Take at night", "None"]', 1, 'Starting at a high dose massively increases the risk of SJS. (First Aid)'),
    (v_topic_id, '140: What happens if you prescribe Valproic Acid and Lamotrigine together?",', '["Nothing", "Valproic acid inhibits the metabolism of Lamotrigine, DOUBLING its levels and massively increasing the risk of SJS. Lamotrigine must be started at half the usual dose.", "None", "None"]', 1, 'A crucial interaction in bipolar management. (MGH Pocket)'),
    (v_topic_id, '141: What happens if you prescribe Carbamazepine and Lamotrigine together?",', '["Nothing", "Carbamazepine INDUCES the metabolism of Lamotrigine, lowering its levels. Lamotrigine dose must be increased.", "None", "None"]', 1, 'Carbamazepine speeds up the liver. (Kaplan & Sadock)'),
    (v_topic_id, '142: Which antipsychotic is famously known for having the highest risk of QTc prolongation?",', '["Olanzapine", "Thioridazine (Typical) and Ziprasidone (Atypical)", "Aripiprazole", "None"]', 1, 'Always check an ECG. (First Aid)'),
    (v_topic_id, '143: A patient taking Haloperidol presents with a stiff, twisted neck that they cannot straighten. Diagnosis?",', '["Tardive Dyskinesia", "Acute Dystonia (specifically, torticollis)", "Akathisia", "None"]', 1, 'Treat immediately with IM Benztropine or Diphenhydramine. (MGH Pocket)'),
    (v_topic_id, '144: A patient taking Risperidone paces the room constantly and says, "I feel like I want to jump out of my skin." Diagnosis?",', '["Mania", "Akathisia", "Anxiety", "None"]', 1, 'Do not misdiagnose this as worsening agitation/psychosis. (Kaplan & Sadock)'),
    (v_topic_id, '145: What is the treatment for Akathisia?",', '["More Risperidone", "Reduce the dose, or add a Beta-blocker (Propranolol), Benztropine, or a Benzodiazepine", "Lithium", "None"]', 1, 'Propranolol is usually first-line. (First Aid)'),
    (v_topic_id, '146: A patient with Schizophrenia has been on Fluphenazine for 20 years. They constantly smack their lips, chew, and exhibit choreoathetoid movements of the fingers. Diagnosis?",', '["Acute dystonia", "Tardive Dyskinesia (TD)", "Huntington''s", "None"]', 1, 'Caused by D2 receptor upregulation/supersensitivity. (MGH Pocket)'),
    (v_topic_id, '147: Which antipsychotic is the treatment of choice for a patient who develops severe Tardive Dyskinesia on a typical antipsychotic?",', '["Haloperidol", "Clozapine (it has virtually zero risk of EPS/TD)", "Risperidone", "None"]', 1, 'Or use a VMAT2 inhibitor like Valbenazine. (Kaplan & Sadock)'),
    (v_topic_id, '148: What is the mechanism of action of Valbenazine (Ingrezza) and Deutetrabenazine?",', '["Dopamine agonists", "Vesicular Monoamine Transporter 2 (VMAT2) inhibitors. They deplete dopamine in the synapse, reducing the hyperkinetic movements of Tardive Dyskinesia.", "None", "None"]', 1, 'The first FDA-approved treatments for TD. (First Aid)'),
    (v_topic_id, '149: Which atypical antipsychotic has the highest risk of hyperprolactinemia?",', '["Quetiapine", "Risperidone (and Paliperidone)", "Clozapine", "None"]', 1, 'Can cause galactorrhea, amenorrhea, and gynecomastia. (MGH Pocket)'),
    (v_topic_id, '150: A patient with Parkinson''s disease develops psychosis (hallucinations). Which atypical antipsychotic is preferred because it has the LEAST D2 antagonism and won''t worsen their Parkinson''s motor symptoms?",', '["Risperidone", "Quetiapine or Pimavanserin", "Haloperidol", "None"]', 1, 'Pimavanserin is a pure 5-HT2A inverse agonist/antagonist with NO dopamine blockade. (Kaplan & Sadock)'),
    (v_topic_id, '151: What is Pimavanserin (Nuplazid) specifically approved for?",', '["Schizophrenia", "Parkinson''s Disease Psychosis", "Depression", "None"]', 1, 'It does not block dopamine, so it doesn''t worsen motor symptoms. (First Aid)'),
    (v_topic_id, '152: A patient presents with severe depression and insomnia. The doctor prescribes an antidepressant that also acts as a potent H1 antagonist. Which drug?",', '["Fluoxetine", "Mirtazapine or Trazodone", "Bupropion", "None"]', 1, 'Exploiting the side effect of sedation for therapeutic benefit. (MGH Pocket)'),
    (v_topic_id, '153: A patient wants to quit smoking. Which antidepressant is FDA approved for this?",', '["Sertraline", "Bupropion (Zyban)", "Lithium", "None"]', 1, 'Varenicline (Chantix) is also used but is not an antidepressant. (Kaplan & Sadock)'),
    (v_topic_id, '154: A patient has depression and severe neuropathic pain. Which class of antidepressants is most appropriate?",', '["SSRIs", "SNRIs (Duloxetine, Venlafaxine) or TCAs (Amitriptyline)", "MAOIs", "None"]', 1, 'Norepinephrine reuptake inhibition is key for pain modulation. (First Aid)'),
    (v_topic_id, '155: A patient with bulimia nervosa is prescribed an antidepressant. Which one is ABSOLUTELY CONTRAINDICATED?",', '["Fluoxetine", "Bupropion", "Sertraline", "None"]', 1, 'Bupropion lowers the seizure threshold; bulimia patients have electrolyte shifts that also lower the threshold, causing seizures. (MGH Pocket)'),
    (v_topic_id, '156: Which antidepressant is the only one FDA-approved for the treatment of Bulimia Nervosa?",', '["Bupropion", "Fluoxetine", "Lithium", "None"]', 1, 'Often requires higher doses (e.g., 60mg) than used for depression. (Kaplan & Sadock)'),
    (v_topic_id, '157: A patient with Bipolar Disorder develops a tremor, weight gain, and acne. They are most likely taking:",', '["Lamotrigine", "Lithium", "Haloperidol", "None"]', 1, 'Acne and psoriasis can be exacerbated by Lithium. (First Aid)'),
    (v_topic_id, '158: A patient taking Valproic Acid presents with acute abdominal pain radiating to the back and vomiting. What test should you order immediately?",', '["ECG", "Lipase and Amylase (to check for acute pancreatitis)", "TSH", "None"]', 1, 'A rare but severe complication of Valproate. (MGH Pocket)'),
    (v_topic_id, '159: Which medication is considered the gold standard for treatment-resistant Schizophrenia?",', '["Haloperidol", "Clozapine", "Risperidone", "None"]', 1, 'Defined as failing at least two adequate trials of other antipsychotics. (Kaplan & Sadock)'),
    (v_topic_id, '160: A patient on Clozapine complains of wetting the bed at night. What is this side effect?",', '["Polyuria", "Enuresis (urinary incontinence)", "Infection", "None"]', 1, 'Clozapine can cause sphincter relaxation. Treat with an anticholinergic if severe, or lower the dose. (First Aid)'),
    (v_topic_id, '161: What is the mechanism of action of Memantine (Namenda) in Alzheimer''s disease?",', '["Cholinesterase inhibitor", "NMDA receptor antagonist (blocks glutamate excitotoxicity)", "Dopamine agonist", "None"]', 1, 'Used for moderate to severe Alzheimer''s. (MGH Pocket)'),
    (v_topic_id, '162: What is the mechanism of action of Donepezil, Rivastigmine, and Galantamine in Alzheimer''s disease?",', '["NMDA antagonists", "Acetylcholinesterase inhibitors (increase acetylcholine in the synapse)", "GABA agonists", "None"]', 1, 'Used for mild to moderate Alzheimer''s. They do not stop the disease, just slow cognitive decline. (Kaplan & Sadock)'),
    (v_topic_id, '163: A patient taking Donepezil presents with bradycardia and frequent syncopal episodes. Why?",', '["Heart attack", "Increased acetylcholine acts on cardiac muscarinic receptors, causing vagal-like slowing of the heart rate (bradycardia)", "Stroke", "None"]', 1, 'A very common reason for stopping these meds in the elderly. (First Aid)'),
    (v_topic_id, '164: A patient with opioid overdose is given Naloxone. They wake up but become extremely combative, nauseous, and have diarrhea. What happened?",', '["They are allergic", "Naloxone precipitated acute opioid withdrawal", "They need more Naloxone", "None"]', 1, 'Withdrawal is miserable but not life-threatening. Maintain the airway. (MGH Pocket)'),
    (v_topic_id, '165: A patient is receiving ECT (Electroconvulsive Therapy) for severe depression. What medication is given right before the shock to paralyze the muscles and prevent bone fractures?",', '["Haloperidol", "Succinylcholine (a depolarizing neuromuscular blocker)", "Propofol", "None"]', 1, 'A short-acting anesthetic (Methohexital or Propofol) is also given so the patient is asleep. (Kaplan & Sadock)'),
    (v_topic_id, '166: A patient with severe anxiety is prescribed Alprazolam (Xanax). Why is this generally not a good long-term solution?",', '["It doesn''t work", "High risk of tolerance, dependence, and severe withdrawal symptoms due to its short half-life", "It causes liver failure", "None"]', 1, 'SSRIs are the first-line long-term treatment for anxiety disorders. (First Aid)'),
    (v_topic_id, '167: What is the primary difference in mechanism between Benzodiazepines and Barbiturates?",', '["None", "Benzos increase FREQUENCY of chloride channel opening. Barbiturates increase DURATION and can open the channel independently at high doses.", "None", "None"]', 1, 'This makes barbiturates much more lethal in overdose (no ceiling effect). (MGH Pocket)'),
    (v_topic_id, '168: A patient is acutely intoxicated with alcohol and highly aggressive. Why should you avoid giving them a Benzodiazepine for sedation?",', '["It won''t work", "Benzodiazepines and alcohol are both CNS depressants (GABA-A agonists); combining them can cause fatal respiratory depression", "It causes mania", "None"]', 1, 'Use an antipsychotic (Haloperidol) instead if chemical restraint is absolutely necessary. (Kaplan & Sadock)'),
    (v_topic_id, '169: A patient with Wernicke''s Encephalopathy (confusion, ataxia, ophthalmoplegia) needs treatment. What must be given FIRST?",', '["Glucose", "Thiamine (Vitamin B1) MUST be given BEFORE or concurrently with Glucose", "Haloperidol", "None"]', 1, 'Giving glucose without thiamine depletes remaining thiamine and permanently damages the mammillary bodies (Korsakoff''s). (First Aid)'),
    (v_topic_id, '170: A patient in the ER has a severe panic attack. You want to give a Benzodiazepine that has a rapid onset. Which one is highly lipophilic and crosses the blood-brain barrier very fast?",', '["Lorazepam", "Diazepam (Valium)", "Clonazepam", "None"]', 1, 'Diazepam kicks in very quickly but also redistributes into fat quickly, so its clinical effect is shorter than its true half-life. (MGH Pocket)'),
    (v_topic_id, '171: A patient wants to switch from Paroxetine (SSRI) to Venlafaxine (SNRI). How should this be done?",', '["Stop Paroxetine and start Venlafaxine immediately", "Cross-tapering (gradually decreasing Paroxetine while gradually increasing Venlafaxine) to avoid withdrawal and serotonin syndrome", "None", "None"]', 1, 'Standard practice for most antidepressant switches (except MAOIs). (Kaplan & Sadock)'),
    (v_topic_id, '172: A patient on Lithium presents with a TSH of 15 (high) and free T4 is low. Do you need to stop the Lithium?",', '["Yes, immediately", "No, Lithium-induced hypothyroidism is easily treated by adding Levothyroxine (thyroid hormone replacement) while continuing Lithium", "None", "None"]', 1, 'Do not throw away a working mood stabilizer if the side effect is easily managed. (First Aid)'),
    (v_topic_id, '173: A patient taking Valproic Acid for bipolar disorder presents with a platelet count of 80,000. What is this?",', '["Leukemia", "Valproate-induced Thrombocytopenia", "Infection", "None"]', 1, 'A common dose-dependent side effect. Monitor CBCs. (MGH Pocket)'),
    (v_topic_id, '174: Which medication is an orexin receptor antagonist used for insomnia?",', '["Zolpidem", "Suvorexant (Belsomra)", "Melatonin", "None"]', 1, 'Blocks the wakefulness pathway rather than inducing the sleep pathway. (Kaplan & Sadock)'),
    (v_topic_id, '175: A patient with narcolepsy is prescribed Modafinil. What is its mechanism of action?",', '["GABA agonist", "It is a non-amphetamine wakefulness-promoting agent (exact mechanism unknown, likely dopamine reuptake inhibition)", "Serotonin agonist", "None"]', 1, 'First-line for narcolepsy and shift-work sleep disorder. (First Aid)'),
    (v_topic_id, '176: A patient with narcolepsy has severe cataplexy (sudden loss of muscle tone triggered by emotion). Which medication is specifically approved for cataplexy?",', '["Modafinil", "Sodium Oxybate (GHB - Gamma-hydroxybutyrate)", "Fluoxetine", "None"]', 1, 'A highly restricted central nervous system depressant taken at night. (MGH Pocket)'),
    (v_topic_id, '177: What is the mechanism of action of Ketamine when used for treatment-resistant depression?",', '["SSRI", "NMDA receptor antagonist. It causes a rapid (within hours) burst of glutamate, leading to synaptogenesis.", "Dopamine agonist", "None"]', 1, 'Esketamine (Spravato) is an FDA-approved intranasal formulation. (Kaplan & Sadock)'),
    (v_topic_id, '178: What is the most common side effect during an Esketamine treatment session?",', '["Seizures", "Dissociation (feeling detached from reality), increased blood pressure, and sedation", "Diarrhea", "None"]', 1, 'Patients must be monitored in the clinic for 2 hours post-dose. (First Aid)'),
    (v_topic_id, '179: A pregnant patient with severe, psychotic depression is not eating or drinking. What is the safest and fastest treatment?",', '["High-dose Haloperidol", "Electroconvulsive Therapy (ECT)", "Lithium", "None"]', 1, 'ECT is highly effective and safe for both mother and fetus. (MGH Pocket)'),
    (v_topic_id, '180: A patient taking Clozapine develops a fever and chest pain. ECG shows ST elevation. Troponins are elevated. Diagnosis?",', '["Panic attack", "Clozapine-induced Myocarditis", "Heartburn", "None"]', 1, 'A fatal complication. Stop Clozapine immediately. (Kaplan & Sadock)'),
    (v_topic_id, '181: Which typical antipsychotic is available in a long-acting injectable (decanoate) formulation?",', '["Chlorpromazine", "Haloperidol and Fluphenazine", "Thioridazine", "None"]', 1, 'Excellent for non-compliant patients. Given every 2-4 weeks. (First Aid)'),
    (v_topic_id, '182: Which atypical antipsychotics are available in long-acting injectable formulations?",', '["None", "Risperidone, Paliperidone, Aripiprazole, Olanzapine", "Clozapine", "None"]', 1, 'Olanzapine LAI requires a 3-hour post-injection observation due to risk of post-injection delirium/sedation syndrome. (MGH Pocket)'),
    (v_topic_id, '183: A patient taking Mirtazapine for depression is gaining too much weight. The doctor switches them to an antidepressant that typically causes weight LOSS. Which one?",', '["Paroxetine", "Bupropion", "TCAs", "None"]', 1, 'Bupropion is structurally related to amphetamines and suppresses appetite. (Kaplan & Sadock)'),
    (v_topic_id, '184: A patient taking an SSRI complains of delayed ejaculation. What off-label medication can be added to help?",', '["More SSRI", "Bupropion, Sildenafil (Viagra), or Cyproheptadine", "Haloperidol", "None"]', 1, 'Or simply switch to a non-SSRI like Bupropion or Mirtazapine. (First Aid)'),
    (v_topic_id, '185: A patient taking Lithium develops severe, cystic acne. What is the management?",', '["Stop Lithium", "Standard dermatological treatments (topicals, antibiotics) while continuing Lithium if it is controlling their bipolar disorder well", "None", "None"]', 1, 'Again, manage the side effect before abandoning the primary treatment. (MGH Pocket)'),
    (v_topic_id, '186: A patient with generalized anxiety disorder wants an anxiolytic but has a history of severe alcohol abuse. Which medication is best?",', '["Alprazolam", "Buspirone, SSRIs, or Hydroxyzine", "Diazepam", "None"]', 1, 'Avoid benzodiazepines in patients with a history of substance abuse. (Kaplan & Sadock)'),
    (v_topic_id, '187: What is the mechanism of action of Hydroxyzine (Vistaril)?",', '["GABA agonist", "A first-generation antihistamine (H1 antagonist) with prominent sedating and anxiolytic properties", "SSRI", "None"]', 1, 'Often used as a non-addictive PRN alternative to benzos for anxiety. (First Aid)'),
    (v_topic_id, '188: A patient taking an MAOI eats a pepperoni pizza. Their blood pressure spikes to 230/130. What medication should be administered in the ER?",', '["Propranolol", "Phentolamine (an alpha-1 antagonist) to rapidly lower blood pressure", "Epinephrine", "None"]', 1, 'A pure alpha-blocker is required to overcome the massive norepinephrine surge. (MGH Pocket)'),
    (v_topic_id, '189: A patient is in severe alcohol withdrawal. They have significant liver cirrhosis. Which Benzodiazepine should you use?",', '["Diazepam", "Lorazepam (or Oxazepam/Temazepam) because they do not require hepatic oxidation, only glucuronidation", "Chlordiazepoxide", "None"]', 1, 'The "LOT" benzos are safe in liver failure. (Kaplan & Sadock)'),
    (v_topic_id, '190: A patient with panic disorder is hyperventilating. They are instructed to breathe into a paper bag. Why does this work?",', '["It distracts them", "It forces them to rebreathe exhaled CO2, correcting the respiratory alkalosis that causes the tingling/dizziness", "It gives them oxygen", "None"]', 1, 'A simple, physiological treatment. (First Aid)'),
    (v_topic_id, '191: A patient taking an SSRI discovers they are pregnant. They are taking Paroxetine. What should be done?",', '["Nothing", "Taper and switch to a safer SSRI like Sertraline or Fluoxetine due to Paroxetine''s association with cardiac defects", "Stop abruptly", "None"]', 1, 'Always taper SSRIs to avoid discontinuation syndrome. (MGH Pocket)'),
    (v_topic_id, '192: A 10-year-old boy is diagnosed with ADHD. The parents refuse stimulant medications. What is the best non-stimulant alternative?",', '["Haloperidol", "Atomoxetine, Guanfacine, or Clonidine", "Lithium", "None"]', 1, 'Atomoxetine is a selective norepinephrine reuptake inhibitor. (Kaplan & Sadock)'),
    (v_topic_id, '193: A patient taking Clozapine complains of excessive drooling (sialorrhea) at night, ruining their pillows. What is a pharmacological treatment for this side effect?",', '["Give more water", "Clonidine (alpha-2 agonist) or Atropine drops sublingually (anticholinergic) to dry secretions", "None", "None"]', 1, 'A very bothersome side effect. (First Aid)'),
    (v_topic_id, '194: What is the mechanism of action of Pramipexole and Ropinirole?",', '["Dopamine antagonists", "Dopamine Agonists", "Serotonin agonists", "None"]', 1, 'Used for Parkinson''s disease and Restless Legs Syndrome (RLS). (MGH Pocket)'),
    (v_topic_id, '195: A patient on an SSRI develops Restless Legs Syndrome. What is the treatment?",', '["More SSRI", "Lower the SSRI dose, or treat with Iron replacement (if ferritin is low) or a Dopamine Agonist (Pramipexole)", "Lithium", "None"]', 1, 'SSRIs and antihistamines can worsen RLS. (Kaplan & Sadock)'),
    (v_topic_id, '196: A patient with severe social anxiety disorder has to give a public speech. They do not want to take a daily medication. What can be given 1 hour before the speech?",', '["Fluoxetine", "Propranolol (Beta-blocker) to block the peripheral autonomic symptoms of performance anxiety (tachycardia, tremor)", "Haloperidol", "None"]', 1, 'Very effective for performance-specific anxiety. (First Aid)'),
    (v_topic_id, '197: A patient with Bipolar Disorder is stabilized on Valproic Acid. They present with acute right upper quadrant pain, jaundice, and elevated AST/ALT. What is the diagnosis?",', '["Gallstones", "Valproate-induced Hepatotoxicity", "Kidney failure", "None"]', 1, 'A black box warning. (MGH Pocket)'),
    (v_topic_id, '198: A patient taking Lamotrigine develops a mild, non-blistering maculopapular rash on their arms. It does not involve mucous membranes. What should you do?",', '["Ignore it", "Discontinue the Lamotrigine immediately. Any rash on Lamotrigine must be assumed to be early Stevens-Johnson Syndrome until proven otherwise.", "Give a steroid cream", "None"]', 1, 'Do not take chances with a Lamotrigine rash. (Kaplan & Sadock)'),
    (v_topic_id, '199: A patient with Schizophrenia refuses to take any daily pills. They are homeless and disorganized. What is the best pharmacological strategy?",', '["Therapy", "A Long-Acting Injectable (LAI) antipsychotic (e.g., Paliperidone Sustenna) given every 1 to 3 months", "ECT", "None"]', 1, 'LAIs drastically reduce relapse rates in non-compliant patients. (First Aid)'),
    (v_topic_id, '200: Final Pearl: When prescribing an antidepressant to a young adult (<24 years old), what FDA Black Box Warning must be discussed?",', '["Weight gain", "Increased risk of suicidal thoughts and behaviors during the initial 1-2 months of treatment", "Seizures", "None"]', 1, 'Patients must be monitored closely when initiating therapy. (MediHelp Mastery)'),
    (v_topic_id, '201: What is the most effective class of medication for treating the positive symptoms of Schizophrenia?', '["SSRIs", "Antipsychotics (Dopamine D2 antagonists)", "Benzodiazepines", "None"]', 1, 'First-line therapy for psychosis. (Kaplan & Sadock)'),
    (v_topic_id, '202: A patient on Haloperidol has a resting tremor, cogwheel rigidity, and a shuffling gait. What is the most appropriate pharmacological treatment if Haloperidol cannot be stopped?', '["Levodopa", "Amantadine or an anticholinergic like Benztropine", "Propranolol", "None"]', 1, 'Treating antipsychotic-induced parkinsonism. Levodopa would worsen the psychosis. (First Aid)'),
    (v_topic_id, '203: A patient taking Valproic Acid presents with tremor, ataxia, and confusion. Ammonia levels are elevated, but liver enzymes are normal. What is the diagnosis?', '["Alcohol withdrawal", "Valproate-induced Hyperammonemic Encephalopathy", "Lithium toxicity", "None"]', 1, 'Can occur even with normal LFTs and normal Valproate levels. Treat with L-carnitine. (MGH Pocket)'),
    (v_topic_id, '204: Which of the following is a known side effect of long-term Lithium use?', '["Hyperthyroidism", "Hypothyroidism", "Cushing''s syndrome", "None"]', 1, 'Lithium inhibits the release of thyroid hormone. (Kaplan & Sadock)'),
    (v_topic_id, '205: A patient with generalized anxiety disorder does not want to take a medication that causes sedation or weight gain. Which of the following is the best option?', '["Mirtazapine", "Buspirone", "Paroxetine", "None"]', 1, 'Buspirone is a 5-HT1A partial agonist that lacks sedation, weight gain, and sexual side effects. (First Aid)'),
    (v_topic_id, '206: A patient taking an SSRI complains of significant sexual dysfunction. Which medication could be substituted to avoid this side effect?', '["Venlafaxine", "Bupropion", "Citalopram", "None"]', 1, 'Bupropion (NDRI) has no serotonergic activity and therefore no sexual side effects. (MGH Pocket)'),
    (v_topic_id, '207: What is the primary mechanism of action of Duloxetine?', '["Selective serotonin reuptake inhibitor", "Serotonin and norepinephrine reuptake inhibitor (SNRI)", "Dopamine antagonist", "None"]', 1, 'Effective for depression and chronic pain. (Kaplan & Sadock)'),
    (v_topic_id, '208: A patient is started on Clozapine. Which of the following must be monitored at baseline and regularly thereafter?', '["ECG only", "Absolute Neutrophil Count (ANC) via the REMS program", "Thyroid function only", "None"]', 1, 'Strict monitoring is required due to the risk of agranulocytosis. (First Aid)'),
    (v_topic_id, '209: What is the mechanism of action of Cyproheptadine in the treatment of Serotonin Syndrome?', '["Serotonin agonist", "Serotonin 5-HT2 receptor antagonist", "Dopamine agonist", "None"]', 1, 'Directly blocks the excessive serotonergic stimulation. (MGH Pocket)'),
    (v_topic_id, '210: A patient taking Lithium develops polyuria and polydipsia. What is the most likely cause?', '["Diabetes Mellitus", "Nephrogenic Diabetes Insipidus", "SIADH", "None"]', 1, 'Lithium desensitizes the kidney to ADH. (Kaplan & Sadock)'),
    (v_topic_id, '211: Which antipsychotic is least likely to cause metabolic syndrome?",', '["Olanzapine", "Aripiprazole", "Quetiapine", "None"]', 1, 'Aripiprazole, Ziprasidone, and Lurasidone are generally weight-neutral. (First Aid)'),
    (v_topic_id, '212: A patient taking an MAOI experiences a hypertensive crisis after eating aged cheese. What is the best treatment?",', '["Propranolol", "Phentolamine", "Epinephrine", "None"]', 1, 'An alpha-adrenergic antagonist is needed to reverse the severe vasoconstriction. (MGH Pocket)'),
    (v_topic_id, '213: Which medication is used for the treatment of opioid withdrawal autonomic symptoms (e.g., tachycardia, sweating)?",', '["Naloxone", "Clonidine", "Methadone", "None"]', 1, 'Clonidine is an alpha-2 agonist that reduces sympathetic outflow. (Kaplan & Sadock)'),
    (v_topic_id, '214: What is the mechanism of action of Naltrexone in alcohol use disorder?",', '["Causes vomiting if alcohol is consumed", "Mu-opioid receptor antagonist (reduces the rewarding effects of alcohol)", "GABA agonist", "None"]', 1, 'Helps reduce heavy drinking days and cravings. (First Aid)'),
    (v_topic_id, '215: A patient with bipolar disorder is taking Lithium and needs a pain reliever for a headache. Which of the following is safest?",', '["Ibuprofen", "Acetaminophen", "Naproxen", "None"]', 1, 'NSAIDs can decrease lithium clearance, leading to toxicity. Acetaminophen is safe. (MGH Pocket)'),
    (v_topic_id, '216: Which antidepressant is classically associated with dose-dependent hypertension?",', '["Fluoxetine", "Venlafaxine", "Bupropion", "None"]', 1, 'Due to its norepinephrine reuptake inhibition at higher doses. (Kaplan & Sadock)'),
    (v_topic_id, '217: A patient taking Haloperidol develops a sudden, sustained, painful contraction of their neck muscles. What is the best treatment?",', '["More Haloperidol", "IM Benztropine or Diphenhydramine", "Propranolol", "None"]', 1, 'Treatment for acute dystonia. (First Aid)'),
    (v_topic_id, '218: Which antipsychotic is the only one FDA-approved for treatment-resistant schizophrenia?",', '["Risperidone", "Clozapine", "Aripiprazole", "None"]', 1, 'Despite its side effects, it is the most effective antipsychotic. (MGH Pocket)'),
    (v_topic_id, '219: What is the mechanism of action of Acamprosate in alcohol use disorder?",', '["Blocks aldehyde dehydrogenase", "Modulates NMDA (glutamate) receptor transmission", "Mu-opioid antagonist", "None"]', 1, 'Helps maintain abstinence by reducing the hyper-excitable state of prolonged withdrawal. (Kaplan & Sadock)'),
    (v_topic_id, '220: A patient taking Mirtazapine is most likely to experience which two side effects?",', '["Weight loss and insomnia", "Weight gain and sedation", "Diarrhea and nausea", "None"]', 1, 'Due to its potent 5-HT2C and H1 antagonism. (First Aid)'),
    (v_topic_id, '221: Which medication is an orexin receptor antagonist used to treat insomnia?",', '["Zolpidem", "Suvorexant", "Ramelteon", "None"]', 1, 'Blocks the wake-promoting neuropeptide orexin. (MGH Pocket)'),
    (v_topic_id, '222: A patient presents with pinpoint pupils, respiratory depression, and coma. What is the immediate treatment?",', '["Flumazenil", "Naloxone", "Physostigmine", "None"]', 1, 'Classic opioid overdose presentation. (Kaplan & Sadock)'),
    (v_topic_id, '223: Which medication is used for smoking cessation and acts as a partial agonist at the alpha-4 beta-2 nicotinic receptor?",', '["Bupropion", "Varenicline (Chantix)", "Clonidine", "None"]', 1, 'Reduces cravings and blunts the rewarding effects of smoking. (First Aid)'),
    (v_topic_id, '224: A patient taking an SSRI develops agitation, hyperreflexia, clonus, and a fever. Diagnosis?",', '["Neuroleptic Malignant Syndrome", "Serotonin Syndrome", "Anticholinergic toxicity", "None"]', 1, 'Hyperreflexia and clonus distinguish it from NMS. (MGH Pocket)'),
    (v_topic_id, '225: What is the mechanism of action of Pramipexole?",', '["Dopamine antagonist", "Dopamine agonist", "Serotonin agonist", "None"]', 1, 'Used in Parkinson''s disease and Restless Legs Syndrome. (Kaplan & Sadock)'),
    (v_topic_id, '226: A patient with ADHD is prescribed Atomoxetine. What is its mechanism of action?",', '["Dopamine and norepinephrine reuptake inhibitor", "Selective norepinephrine reuptake inhibitor (SNRI)", "Alpha-2 agonist", "None"]', 1, 'A non-stimulant option for ADHD. (First Aid)'),
    (v_topic_id, '227: Which benzodiazepine is preferred in patients with severe liver disease due to its metabolism via glucuronidation?",', '["Diazepam", "Lorazepam (or Oxazepam/Temazepam)", "Chlordiazepoxide", "None"]', 1, 'The "LOT" benzos bypass phase 1 hepatic oxidation. (MGH Pocket)'),
    (v_topic_id, '228: A patient taking Valproic Acid for bipolar disorder presents with severe abdominal pain and elevated lipase. Diagnosis?",', '["Hepatitis", "Valproate-induced pancreatitis", "Gallstones", "None"]', 1, 'A rare but serious complication. (Kaplan & Sadock)'),
    (v_topic_id, '229: What is the most severe dermatologic complication associated with Lamotrigine?",', '["Psoriasis", "Stevens-Johnson Syndrome (SJS)", "Acne", "None"]', 1, 'Risk is highest with rapid dose titration or co-administration with Valproate. (First Aid)'),
    (v_topic_id, '230: Which atypical antipsychotic has the highest risk of causing hyperprolactinemia?",', '["Quetiapine", "Risperidone", "Clozapine", "None"]', 1, 'Due to its strong D2 antagonism in the tuberoinfundibular pathway. (MGH Pocket)'),
    (v_topic_id, '231: A patient taking a TCA presents with a widened QRS complex on ECG. What is the best treatment?",', '["Amiodarone", "Sodium Bicarbonate", "Lidocaine", "None"]', 1, 'Overcomes the sodium channel blockade. (Kaplan & Sadock)'),
    (v_topic_id, '232: What is the primary use of Buprenorphine in psychiatry?",', '["Treating severe depression", "Medication-Assisted Treatment (MAT) for Opioid Use Disorder", "Treating ADHD", "None"]', 1, 'It is a partial mu-opioid agonist. (First Aid)'),
    (v_topic_id, '233: A patient taking an SSRI complains of "brain zaps" after missing their medication for 3 days. What is this?",', '["Serotonin Syndrome", "Antidepressant Discontinuation Syndrome", "A seizure", "None"]', 1, 'Common with short half-life SSRIs/SNRIs like Paroxetine and Venlafaxine. (MGH Pocket)'),
    (v_topic_id, '234: What is the mechanism of action of Memantine in Alzheimer''s disease?",', '["Acetylcholinesterase inhibitor", "NMDA receptor antagonist", "Dopamine agonist", "None"]', 1, 'Protects neurons from glutamate-mediated excitotoxicity. (Kaplan & Sadock)'),
    (v_topic_id, '235: A patient with Parkinson''s disease psychosis needs an antipsychotic. Which medication is FDA-approved specifically for this and does not block D2 receptors?",', '["Quetiapine", "Pimavanserin", "Clozapine", "None"]', 1, 'It is a selective 5-HT2A inverse agonist/antagonist. (First Aid)'),
    (v_topic_id, '236: Which medication is an irreversible inhibitor of aldehyde dehydrogenase used as aversive therapy for alcohol use disorder?",', '["Naltrexone", "Disulfiram (Antabuse)", "Acamprosate", "None"]', 1, 'Causes a severe reaction if alcohol is consumed. (MGH Pocket)'),
    (v_topic_id, '237: A patient is prescribed Lithium. What happens to the Lithium level if they become severely dehydrated?",', '["It decreases", "It increases significantly, leading to potential toxicity", "It stays the same", "None"]', 1, 'The kidneys reabsorb lithium along with sodium when dehydrated. (Kaplan & Sadock)'),
    (v_topic_id, '238: Which of the following is a classic side effect of Trazodone?",', '["Hypertension", "Priapism and sedation", "Weight loss", "None"]', 1, 'Priapism is a rare but emergent side effect due to alpha-1 blockade. (First Aid)'),
    (v_topic_id, '239: A patient taking Haloperidol constantly paces and cannot sit still. Diagnosis?",', '["Acute dystonia", "Akathisia", "Tardive dyskinesia", "None"]', 1, 'A very uncomfortable feeling of inner restlessness. (MGH Pocket)'),
    (v_topic_id, '240: What is the pharmacological treatment of choice for Akathisia?",', '["More Haloperidol", "Propranolol (Beta-blocker)", "Lithium", "None"]', 1, 'First-line treatment to reduce the inner restlessness. (Kaplan & Sadock)'),
    (v_topic_id, '241: Which of the following medications is a Vesicular Monoamine Transporter 2 (VMAT2) inhibitor used for Tardive Dyskinesia?",', '["Benztropine", "Valbenazine", "Propranolol", "None"]', 1, 'Deutetrabenazine is another VMAT2 inhibitor used for this purpose. (First Aid)'),
    (v_topic_id, '242: A patient presents with acute opioid withdrawal. Which medication is a full mu-opioid agonist used in clinics for long-term maintenance?",', '["Buprenorphine", "Methadone", "Naltrexone", "None"]', 1, 'Long half-life prevents withdrawal and reduces cravings. (MGH Pocket)'),
    (v_topic_id, '243: What is the mechanism of action of Buspirone?",', '["GABA agonist", "5-HT1A partial agonist", "Dopamine antagonist", "None"]', 1, 'Used for generalized anxiety disorder; non-sedating and non-addictive. (Kaplan & Sadock)'),
    (v_topic_id, '244: A patient taking an SSRI wants to take St. John''s Wort. What is the risk?",', '["No risk", "Increased risk of Serotonin Syndrome", "Hypertensive crisis", "None"]', 1, 'St. John''s Wort is a potent herbal serotonergic agent. (First Aid)'),
    (v_topic_id, '245: Which atypical antipsychotic requires routine absolute neutrophil count (ANC) monitoring due to the risk of agranulocytosis?",', '["Risperidone", "Clozapine", "Olanzapine", "None"]', 1, 'Monitored via the REMS program. (MGH Pocket)'),
    (v_topic_id, '246: A patient with bipolar disorder is started on Carbamazepine. What hematologic side effect must be monitored?",', '["Polycythemia", "Aplastic anemia / Agranulocytosis", "Thrombocytosis", "None"]', 1, 'Can cause severe bone marrow suppression. (Kaplan & Sadock)'),
    (v_topic_id, '247: What is the mechanism of action of Ramelteon?",', '["GABA agonist", "Melatonin receptor agonist (MT1 and MT2)", "Orexin antagonist", "None"]', 1, 'Used for sleep-onset insomnia. (First Aid)'),
    (v_topic_id, '248: A patient taking Clozapine develops excessive drooling (sialorrhea). What medication can be used to treat this?",', '["Propranolol", "Clonidine or anticholinergic drops (e.g., Atropine sublingually)", "Lithium", "None"]', 1, 'Helps dry the excessive secretions. (MGH Pocket)'),
    (v_topic_id, '249: Which SSRI has the longest half-life, making it less likely to cause discontinuation syndrome?",', '["Paroxetine", "Fluoxetine", "Sertraline", "None"]', 1, 'Its active metabolite has a half-life of 1-2 weeks. (Kaplan & Sadock)'),
    (v_topic_id, '250: Final Pearl: What is the difference between Buprenorphine and Methadone in the treatment of Opioid Use Disorder?",', '["There is no difference", "Methadone is a FULL mu-opioid agonist; Buprenorphine is a PARTIAL mu-opioid agonist with a high binding affinity.", "None", "None"]', 1, 'Both are highly effective, but buprenorphine has a ceiling effect for respiratory depression. (MediHelp Mastery)'),
    (v_topic_id, '251: Which of the following antidepressants acts as an antagonist at the 5-HT2 receptor and inhibits serotonin reuptake, but is highly sedating and primarily used for sleep?', '["Fluoxetine", "Trazodone", "Bupropion", "None"]', 1, 'Trazodone is rarely used at antidepressant doses due to extreme sedation. (Kaplan & Sadock)'),
    (v_topic_id, '252: A patient taking an MAOI must avoid aged cheeses to prevent hypertensive crisis. What other common food/drink must be avoided?', '["Milk", "Tap or draft beer (and red wine)", "Apple juice", "None"]', 1, 'Draft beers and some wines contain high levels of tyramine. (First Aid)'),
    (v_topic_id, '253: A patient is prescribed Lithium. What routine monitoring is required every 6-12 months?', '["ECG only", "Serum Lithium level, TSH, and BUN/Creatinine", "Liver function tests", "None"]', 1, 'Monitoring for therapeutic levels, hypothyroidism, and renal impairment. (MGH Pocket)'),
    (v_topic_id, '254: Which atypical antipsychotic requires taking the medication with at least 350 calories to ensure proper absorption?', '["Olanzapine", "Lurasidone (Latuda)", "Aripiprazole", "None"]', 1, 'Ziprasidone requires 500 calories. Lurasidone requires 350. (Kaplan & Sadock)'),
    (v_topic_id, '255: A patient with bipolar disorder develops a fine resting tremor shortly after starting a new medication. Which medication is the most likely cause?', '["Valproate", "Lithium", "Lamotrigine", "None"]', 1, 'A common, non-toxic side effect of Lithium. (First Aid)'),
    (v_topic_id, '256: What is the pharmacological mechanism by which typical antipsychotics cause hyperprolactinemia?', '["Serotonin blockade", "Dopamine D2 blockade in the tuberoinfundibular pathway", "Histamine blockade", "None"]', 1, 'Dopamine tonically inhibits prolactin release. Blocking dopamine increases prolactin. (MGH Pocket)'),
    (v_topic_id, '257: A patient taking Haloperidol presents with a subjective feeling of intense inner restlessness and constantly shifts their weight from foot to foot. Diagnosis?', '["Agitation", "Akathisia", "Parkinsonism", "None"]', 1, 'Often misdiagnosed as worsening psychiatric agitation. (Kaplan & Sadock)'),
    (v_topic_id, '258: Which class of medications is first-line for treating ADHD in children?', '["SSRIs", "Stimulants (Methylphenidate, Amphetamines)", "Antipsychotics", "None"]', 1, 'Highly effective, working primarily via dopamine and norepinephrine reuptake inhibition. (First Aid)'),
    (v_topic_id, '259: What is the primary use of Naloxone?",', '["Long-term opioid maintenance", "Immediate reversal of acute opioid overdose (respiratory depression)", "Pain relief", "None"]', 1, 'Short half-life means patients must be monitored for re-sedation. (MGH Pocket)'),
    (v_topic_id, '260: Which mood stabilizer is most strongly associated with causing polycystic ovary syndrome (PCOS) in women?",', '["Lithium", "Valproic Acid", "Lamotrigine", "None"]', 1, 'Can cause weight gain, insulin resistance, and hyperandrogenism. (Kaplan & Sadock)'),
    (v_topic_id, '261: A patient taking a TCA presents with severe anticholinergic toxicity (dry mouth, blurred vision, urinary retention). What other vital sign abnormality is expected?",', '["Bradycardia", "Tachycardia", "Hypothermia", "None"]', 1, 'Anticholinergic effects cause tachycardia (blocking vagal tone). (First Aid)'),
    (v_topic_id, '262: Which atypical antipsychotic is most structurally and functionally similar to Clozapine, but does NOT carry the high risk of agranulocytosis?",', '["Risperidone", "Olanzapine", "Aripiprazole", "None"]', 1, 'Olanzapine shares the high risk of metabolic syndrome with Clozapine. (MGH Pocket)'),
    (v_topic_id, '263: A patient taking an SSRI for 3 weeks states, "I still feel depressed." What is the appropriate clinical response?",', '["Stop the drug immediately", "Reassure the patient that full therapeutic effect can take 4-6 weeks and continue the current dose", "Add Lithium", "None"]', 1, 'Patience is required when initiating SSRIs. (Kaplan & Sadock)'),
    (v_topic_id, '264: Which medication is a selective norepinephrine reuptake inhibitor (SNRI) used specifically for ADHD?",', '["Bupropion", "Atomoxetine", "Venlafaxine", "None"]', 1, 'A non-stimulant alternative for ADHD. (First Aid)'),
    (v_topic_id, '265: A patient with bipolar disorder is manic and refusing oral medications. The team decides to use an IM typical antipsychotic. Which is most commonly used?",', '["IM Chlorpromazine", "IM Haloperidol", "IM Thioridazine", "None"]', 1, 'Haloperidol is the standard typical antipsychotic for acute IM chemical restraint. (MGH Pocket)'),
    (v_topic_id, '266: What is the primary difference between Escitalopram and Citalopram?",', '["They are different classes", "Escitalopram is the S-enantiomer (the active enantiomer) of the racemic mixture Citalopram", "None", "None"]', 1, 'Escitalopram is essentially a purified, more potent version of Citalopram. (Kaplan & Sadock)'),
    (v_topic_id, '267: A patient taking Valproic Acid presents with new-onset jaundice and abdominal pain. What is the most critical lab to check?",', '["CBC", "Liver Function Tests (AST/ALT) due to the risk of severe hepatotoxicity", "Lipid panel", "None"]', 1, 'A known black box warning for Valproate. (First Aid)'),
    (v_topic_id, '268: Which of the following is a primary side effect of Atomoxetine?",', '["Weight gain", "Decreased appetite and GI upset", "Severe sedation", "None"]', 1, 'Can also cause slight increases in heart rate and blood pressure. (MGH Pocket)'),
    (v_topic_id, '269: A patient with generalized anxiety disorder wants to avoid sexual side effects. Which medication could be prescribed?",', '["Paroxetine", "Buspirone", "Sertraline", "None"]', 1, 'Buspirone lacks the sexual side effects common with SSRIs. (Kaplan & Sadock)'),
    (v_topic_id, '270: A patient taking Clozapine has a seizure. Is this a known complication?",', '["No", "Yes, Clozapine lowers the seizure threshold in a dose-dependent manner", "Only if they drink alcohol", "None"]', 1, 'A major black box warning for Clozapine. (First Aid)'),
    (v_topic_id, '271: Which medication is an alpha-2 agonist used for both ADHD and the autonomic symptoms of opioid withdrawal?",', '["Propranolol", "Clonidine", "Phentolamine", "None"]', 1, 'Reduces sympathetic outflow from the locus coeruleus. (MGH Pocket)'),
    (v_topic_id, '272: A patient presents with priapism after starting a new antidepressant for sleep. Which medication?",', '["Fluoxetine", "Trazodone", "Mirtazapine", "None"]', 1, 'Alpha-1 blockade in the corpus cavernosum traps blood. (Kaplan & Sadock)'),
    (v_topic_id, '273: What is the primary mechanism of action of Lithium?",', '["Dopamine antagonist", "Exact mechanism unknown, but it is believed to inhibit inositol monophosphatase (IP3 pathway) and Glycogen Synthase Kinase 3 (GSK-3)", "Serotonin agonist", "None"]', 1, 'The oldest and most classic mood stabilizer. (First Aid)'),
    (v_topic_id, '274: A patient taking Mirtazapine is most likely to complain of which two side effects?",', '["Weight loss and insomnia", "Significant weight gain and sedation", "Diarrhea and headache", "None"]', 1, 'Due to its potent anti-histamine (H1) and 5-HT2C blockade. (MGH Pocket)'),
    (v_topic_id, '275: Which SSRI is most notoriously associated with severe withdrawal (discontinuation) syndrome if stopped abruptly?",', '["Fluoxetine", "Paroxetine", "Citalopram", "None"]', 1, 'Due to its very short half-life. (Kaplan & Sadock)'),
    (v_topic_id, '276: A patient with bipolar disorder is started on Lamotrigine. Why must the dose be titrated so slowly over several weeks?",', '["To prevent seizures", "To minimize the risk of developing Stevens-Johnson Syndrome (SJS)", "To prevent liver failure", "None"]', 1, 'Rapid titration is the #1 risk factor for Lamotrigine-induced SJS. (First Aid)'),
    (v_topic_id, '277: Which typical antipsychotic is classically associated with pigmentary retinopathy leading to blindness?",', '["Haloperidol", "Thioridazine", "Chlorpromazine", "None"]', 1, 'A unique and severe side effect of Thioridazine. (MGH Pocket)'),
    (v_topic_id, '278: A patient taking Haloperidol develops a slow, shuffling gait and resting tremor. What is the best initial pharmacological treatment?",', '["Levodopa", "Benztropine (or Amantadine)", "Propranolol", "None"]', 1, 'Treating antipsychotic-induced parkinsonism with an anticholinergic. (Kaplan & Sadock)'),
    (v_topic_id, '279: Which atypical antipsychotic requires routine ECG monitoring due to its high risk of QTc prolongation?",', '["Aripiprazole", "Ziprasidone", "Lurasidone", "None"]', 1, 'Ziprasidone (Geodon) has one of the highest risks of QTc prolongation among atypicals. (First Aid)'),
    (v_topic_id, '280: A patient taking an MAOI eats smoked fish and experiences a sudden, severe headache. What is happening?",', '["Migraine", "Hypertensive crisis due to tyramine ingestion", "Stroke", "None"]', 1, 'Tyramine acts as an indirect sympathomimetic when MAO is inhibited. (MGH Pocket)'),
    (v_topic_id, '281: What is the pharmacological mechanism of action of Varenicline?",', '["Full nicotine agonist", "Partial agonist at the alpha-4 beta-2 nicotinic acetylcholine receptor", "Dopamine antagonist", "None"]', 1, 'Reduces cravings and blunts the reward of smoking. (Kaplan & Sadock)'),
    (v_topic_id, '282: Which medication is used to prevent relapse in alcohol use disorder by causing a severe physical reaction if alcohol is consumed?",', '["Naltrexone", "Disulfiram", "Acamprosate", "None"]', 1, 'Irreversibly inhibits aldehyde dehydrogenase. (First Aid)'),
    (v_topic_id, '283: A patient taking Lithium develops severe diarrhea, vomiting, and ataxia. What is the next immediate step?",', '["Give antiemetics", "Hold the Lithium and check a serum Lithium level immediately (suspect toxicity)", "Give IV fluids only", "None"]', 1, 'Clinical signs of Lithium toxicity require immediate assessment. (MGH Pocket)'),
    (v_topic_id, '284: Which antidepressant is an NDRI and is contraindicated in patients with seizure disorders?",', '["Venlafaxine", "Bupropion", "Mirtazapine", "None"]', 1, 'Bupropion lowers the seizure threshold. (Kaplan & Sadock)'),
    (v_topic_id, '285: A patient with ADHD and a history of substance abuse needs treatment. Which non-stimulant medication is a selective norepinephrine reuptake inhibitor?",', '["Guanfacine", "Atomoxetine", "Clonidine", "None"]', 1, 'Atomoxetine has no abuse potential. (First Aid)'),
    (v_topic_id, '286: Which atypical antipsychotic is most commonly associated with metabolic syndrome (massive weight gain, diabetes, hyperlipidemia)?",', '["Aripiprazole", "Olanzapine (and Clozapine)", "Ziprasidone", "None"]', 1, 'Patients on Olanzapine must have their weight, BP, lipids, and A1c monitored regularly. (MGH Pocket)'),
    (v_topic_id, '287: A patient taking Clozapine complains of excessive drooling, especially at night. What is this called?",', '["Polyuria", "Sialorrhea", "Enuresis", "None"]', 1, 'A paradoxical side effect of Clozapine due to M4 receptor agonism. (Kaplan & Sadock)'),
    (v_topic_id, '288: A patient is prescribed Duloxetine. What is the mechanism of action?",', '["SSRI", "Serotonin and Norepinephrine Reuptake Inhibitor (SNRI)", "TCA", "None"]', 1, 'Often used for depression with comorbid neuropathic pain. (First Aid)'),
    (v_topic_id, '289: Which class of medications is the most effective for treating the acute positive symptoms of schizophrenia?",', '["Antidepressants", "Antipsychotics", "Mood stabilizers", "None"]', 1, 'Antipsychotics are the cornerstone of schizophrenia treatment. (MGH Pocket)'),
    (v_topic_id, '290: A patient taking a TCA intentionally overdoses. They present with a widened QRS complex. What is the antidote?",', '["Naloxone", "IV Sodium Bicarbonate", "Flumazenil", "None"]', 1, 'Alkalinizes the blood and overcomes the sodium channel blockade. (Kaplan & Sadock)'),
    (v_topic_id, '291: Which medication is a pure opioid antagonist used to reverse acute opioid overdose?",', '["Methadone", "Naloxone", "Buprenorphine", "None"]', 1, 'Naloxone kicks opioids off the mu receptors immediately. (First Aid)'),
    (v_topic_id, '292: A patient taking Lithium is prescribed a Thiazide diuretic for hypertension. What is the expected drug-drug interaction?",', '["Lithium level decreases", "Lithium level INCREASES significantly, leading to toxicity", "No interaction", "None"]', 1, 'Thiazides cause the kidneys to reabsorb sodium and Lithium. (MGH Pocket)'),
    (v_topic_id, '293: Which medication is a partial mu-opioid agonist used for Medication-Assisted Treatment (MAT) of Opioid Use Disorder?",', '["Methadone", "Buprenorphine", "Naltrexone", "None"]', 1, 'Binds tightly but with low intrinsic activity. (Kaplan & Sadock)'),
    (v_topic_id, '294: A patient taking Risperidone develops bilateral breast enlargement and milky discharge. What is the mechanism?",', '["Serotonin excess", "Dopamine D2 blockade leading to hyperprolactinemia", "Histamine blockade", "None"]', 1, 'Risperidone is notorious for elevating prolactin levels. (First Aid)'),
    (v_topic_id, '295: A patient with bipolar disorder is manic. Which of the following medications is NOT appropriate as monotherapy?",', '["Lithium", "Sertraline (or any antidepressant)", "Valproic Acid", "None"]', 1, 'Antidepressants can precipitate mania if given without a mood stabilizer. (MGH Pocket)'),
    (v_topic_id, '296: Which atypical antipsychotic is known as a partial D2 agonist?",', '["Quetiapine", "Aripiprazole", "Olanzapine", "None"]', 1, 'Aripiprazole acts as a stabilizer of dopamine transmission. (Kaplan & Sadock)'),
    (v_topic_id, '297: A patient taking Valproic Acid wants to get pregnant. Why is this contraindicated?",', '["It causes bleeding", "Valproic Acid causes Neural Tube Defects (e.g., Spina Bifida)", "It causes heart defects", "None"]', 1, 'Always switch to a safer alternative before conception if possible. (First Aid)'),
    (v_topic_id, '298: Which atypical antipsychotic requires strict monitoring of the Absolute Neutrophil Count (ANC) due to the risk of agranulocytosis?",', '["Risperidone", "Clozapine", "Quetiapine", "None"]', 1, 'The Clozapine REMS program is mandatory. (MGH Pocket)'),
    (v_topic_id, '299: A patient presents with acute catatonia. You perform a Lorazepam challenge. What is the expected outcome if the diagnosis is catatonia?",', '["They get worse", "They rapidly awaken and temporarily resume normal behavior/speech", "Nothing happens", "None"]', 1, 'Benzodiazepines are highly effective for acute catatonia. (Kaplan & Sadock)'),
    (v_topic_id, '300: Which medication is an NMDA receptor antagonist used to treat moderate to severe Alzheimer''s Disease?",', '["Donepezil", "Memantine", "Rivastigmine", "None"]', 1, 'Protects neurons from glutamate excitotoxicity. (First Aid)'),
    (v_topic_id, '301: A patient taking Haloperidol develops severe muscle rigidity, a fever of 105F, and elevated CK. Diagnosis?",', '["Serotonin Syndrome", "Neuroleptic Malignant Syndrome (NMS)", "Catatonia", "None"]', 1, 'A life-threatening complication of dopamine blockade. (MGH Pocket)'),
    (v_topic_id, '302: What is the mechanism of action of Acamprosate?",', '["Blocks aldehyde dehydrogenase", "NMDA (glutamate) receptor antagonist, reducing hyper-excitability in alcohol withdrawal/recovery", "Opioid antagonist", "None"]', 1, 'Helps maintain abstinence in alcohol use disorder. (Kaplan & Sadock)'),
    (v_topic_id, '303: Which SSRI has the longest half-life?",', '["Paroxetine", "Fluoxetine", "Sertraline", "None"]', 1, 'Due to its active metabolite, norfluoxetine. (First Aid)'),
    (v_topic_id, '304: A patient taking Mirtazapine is likely to experience what side effect due to its potent antihistamine properties?",', '["Insomnia", "Sedation and weight gain", "Diarrhea", "None"]', 1, 'Often used intentionally in elderly patients who are depressed, underweight, and not sleeping. (MGH Pocket)'),
    (v_topic_id, '305: Which medication is an orexin receptor antagonist used for insomnia?",', '["Zolpidem", "Suvorexant", "Ramelteon", "None"]', 1, 'Blocks the wakefulness pathway. (Kaplan & Sadock)'),
    (v_topic_id, '306: A patient with narcolepsy has severe cataplexy. Which restricted medication is specifically approved for this?",', '["Modafinil", "Sodium Oxybate (GHB)", "Methylphenidate", "None"]', 1, 'Given at night to consolidate sleep and reduce daytime cataplexy. (First Aid)'),
    (v_topic_id, '307: What is the antidote for Benzodiazepine overdose?",', '["Naloxone", "Flumazenil", "Fomepizole", "None"]', 1, 'Use with caution as it can precipitate seizures in dependent patients. (MGH Pocket)'),
    (v_topic_id, '308: Which benzodiazepine is preferred in a patient with severe liver cirrhosis?",', '["Diazepam", "Lorazepam (or Oxazepam, Temazepam)", "Alprazolam", "None"]', 1, 'The "LOT" benzos do not require hepatic oxidation. (Kaplan & Sadock)'),
    (v_topic_id, '309: A patient taking Lamotrigine and Valproic Acid together is at massively increased risk for what complication?",', '["Liver failure", "Stevens-Johnson Syndrome (SJS)", "Kidney failure", "None"]', 1, 'Valproate doubles the concentration of Lamotrigine. (First Aid)'),
    (v_topic_id, '310: Which medication is a VMAT2 inhibitor used to treat Tardive Dyskinesia?",', '["Benztropine", "Valbenazine (or Deutetrabenazine)", "Propranolol", "None"]', 1, 'Depletes dopamine in the synapse to reduce hyperkinetic movements. (MGH Pocket)'),
    (v_topic_id, '311: A patient taking an SSRI for depression develops sexual dysfunction and wants to switch to an alternative. Which of the following is the best choice?', '["Paroxetine", "Bupropion", "Clomipramine", "None"]', 1, 'Bupropion is an NDRI and does not cause sexual dysfunction. (Kaplan & Sadock)'),
    (v_topic_id, '312: Which of the following is a classic side effect of Topiramate?', '["Weight gain", "Cognitive dulling (''''Dopamax'''') and word-finding difficulty", "Hyperactivity", "None"]', 1, 'Also causes kidney stones and weight loss. (First Aid)'),
    (v_topic_id, '313: A patient taking Carbamazepine develops a sore throat, fever, and mouth ulcers. What is the most critical lab to check?', '["Liver function tests", "Complete Blood Count (CBC) to check for Agranulocytosis", "Lipid panel", "None"]', 1, 'A black box warning for Carbamazepine. (MGH Pocket)'),
    (v_topic_id, '314: What is the primary mechanism of action of Ketamine in the treatment of depression?', '["Serotonin reuptake inhibitor", "NMDA receptor antagonist (glutamate modulator)", "Dopamine agonist", "None"]', 1, 'Causes a rapid burst of glutamate and synaptogenesis. (Kaplan & Sadock)'),
    (v_topic_id, '315: Which medication is FDA-approved for the treatment of Bulimia Nervosa?', '["Sertraline", "Fluoxetine", "Bupropion", "None"]', 1, 'Often requires higher doses than for depression. Bupropion is strictly contraindicated. (First Aid)'),
    (v_topic_id, '316: A patient taking Haloperidol develops severe muscle rigidity, high fever, and autonomic instability. What is the diagnosis?', '["Serotonin Syndrome", "Neuroleptic Malignant Syndrome (NMS)", "Catatonia", "None"]', 1, 'A life-threatening reaction to dopamine blockade. (MGH Pocket)'),
    (v_topic_id, '317: Which class of antidepressants is contraindicated in patients with a history of narrow-angle glaucoma?', '["SSRIs", "Tricyclic Antidepressants (TCAs)", "SNRIs", "None"]', 1, 'Due to their potent anticholinergic effects. (Kaplan & Sadock)'),
    (v_topic_id, '318: A patient taking an MAOI experiences a severe headache and high blood pressure after eating aged cheese. What is the appropriate treatment?', '["Beta blocker", "Phentolamine (alpha-1 antagonist)", "Epinephrine", "None"]', 1, 'Alpha blockade is required to reverse the massive sympathetic surge. (First Aid)'),
    (v_topic_id, '319: What is the primary mechanism of action of Buspirone?', '["GABA agonist", "5-HT1A partial agonist", "Dopamine antagonist", "None"]', 1, 'Used for generalized anxiety disorder; non-sedating. (MGH Pocket)'),
    (v_topic_id, '320: Which atypical antipsychotic is most famously associated with hyperprolactinemia?",', '["Quetiapine", "Risperidone", "Aripiprazole", "None"]', 1, 'It has the tightest D2 binding among atypicals. (Kaplan & Sadock)'),
    (v_topic_id, '321: A patient taking Lamotrigine develops a rapidly spreading rash with mucosal involvement. What is the diagnosis?",', '["Acne", "Stevens-Johnson Syndrome (SJS)", "Psoriasis", "None"]', 1, 'A dermatologic emergency requiring immediate cessation of the drug. (First Aid)'),
    (v_topic_id, '322: Which medication is an orexin receptor antagonist used for insomnia?",', '["Zolpidem", "Suvorexant", "Ramelteon", "None"]', 1, 'Blocks the wakefulness pathway. (MGH Pocket)'),
    (v_topic_id, '323: A patient taking Clozapine has a routine CBC. The Absolute Neutrophil Count (ANC) is 400. What is the next step?",', '["Lower the dose", "Stop Clozapine immediately (Agranulocytosis)", "Give an antibiotic", "None"]', 1, 'A severe and potentially fatal complication. (Kaplan & Sadock)'),
    (v_topic_id, '324: What is the mechanism of action of Mirtazapine?",', '["Serotonin reuptake inhibitor", "Alpha-2 antagonist (increases release of NE and 5-HT)", "Dopamine agonist", "None"]', 1, 'Also a potent H1 antagonist (causing sedation and weight gain). (First Aid)'),
    (v_topic_id, '325: A patient taking Lithium develops severe polyuria and polydipsia. What is the diagnosis?",', '["Diabetes Mellitus", "Nephrogenic Diabetes Insipidus", "SIADH", "None"]', 1, 'Lithium desensitizes the collecting duct to ADH. (MGH Pocket)'),
    (v_topic_id, '326: Which SSRI is notoriously teratogenic (associated with cardiac septal defects)?",', '["Sertraline", "Paroxetine", "Fluoxetine", "None"]', 1, 'Generally avoided in pregnancy. (Kaplan & Sadock)'),
    (v_topic_id, '327: A patient taking Valproic Acid is at risk for which severe complication affecting the abdomen?",', '["Gallstones", "Pancreatitis (and Hepatotoxicity)", "Appendicitis", "None"]', 1, 'Check lipase, amylase, and LFTs if abdominal pain occurs. (First Aid)'),
    (v_topic_id, '328: Which medication is used for Medication-Assisted Treatment (MAT) of Opioid Use Disorder and acts as a full mu-opioid agonist?",', '["Buprenorphine", "Methadone", "Naltrexone", "None"]', 1, 'Given daily in a specialized clinic. (MGH Pocket)'),
    (v_topic_id, '329: A patient presents with acute catatonia. What is the initial pharmacological treatment?",', '["Haloperidol", "Lorazepam (Benzodiazepine challenge)", "Fluoxetine", "None"]', 1, 'Highly effective for breaking the catatonic state. (Kaplan & Sadock)'),
    (v_topic_id, '330: What is the mechanism of action of Varenicline (Chantix)?",', '["Nicotine antagonist", "Partial agonist at the alpha-4 beta-2 nicotinic acetylcholine receptor", "Dopamine antagonist", "None"]', 1, 'Used for smoking cessation. (First Aid)'),
    (v_topic_id, '331: Which atypical antipsychotic requires taking the medication with at least 500 calories of food?",', '["Olanzapine", "Ziprasidone", "Risperidone", "None"]', 1, 'Absorption drops by 50% without food. (MGH Pocket)'),
    (v_topic_id, '332: A patient taking a TCA intentionally overdoses. What ECG finding is pathognomonic for severe toxicity?",', '["ST elevation", "Widened QRS complex", "Peaked T waves", "None"]', 1, 'Predicts risk of seizures and ventricular arrhythmias. (Kaplan & Sadock)'),
    (v_topic_id, '333: Which medication is a non-stimulant selective norepinephrine reuptake inhibitor used for ADHD?",', '["Bupropion", "Atomoxetine", "Clonidine", "None"]', 1, 'Useful for patients with a history of substance abuse. (First Aid)'),
    (v_topic_id, '334: A patient taking Haloperidol develops a slow, shuffling gait and cogwheel rigidity. What is the treatment?",', '["Levodopa", "Benztropine or Amantadine", "Propranolol", "None"]', 1, 'Treating antipsychotic-induced parkinsonism. (MGH Pocket)'),
    (v_topic_id, '335: What is the primary mechanism of action of Donepezil in Alzheimer''s Disease?",', '["NMDA antagonist", "Acetylcholinesterase inhibitor", "GABA agonist", "None"]', 1, 'Increases acetylcholine in the synapse to slow cognitive decline. (Kaplan & Sadock)'),
    (v_topic_id, '336: A patient with generalized anxiety disorder is prescribed a medication that takes 2-4 weeks to work and has no abuse potential. Which medication?",', '["Alprazolam", "Buspirone", "Diazepam", "None"]', 1, 'It is a 5-HT1A partial agonist. (First Aid)'),
    (v_topic_id, '337: Which atypical antipsychotic has the lowest risk of metabolic syndrome but a high risk of QTc prolongation?",', '["Olanzapine", "Ziprasidone", "Clozapine", "None"]', 1, 'Aripiprazole and Lurasidone are also weight-neutral but with less QTc risk. (MGH Pocket)'),
    (v_topic_id, '338: A patient taking Lithium is prescribed Ibuprofen for a headache. What is the expected drug interaction?",', '["Lithium level decreases", "Lithium level INCREASES (risk of toxicity)", "No interaction", "None"]', 1, 'NSAIDs decrease renal blood flow, reducing lithium clearance. (Kaplan & Sadock)'),
    (v_topic_id, '339: Which SSRI has the shortest half-life and is most likely to cause discontinuation syndrome?",', '["Fluoxetine", "Paroxetine", "Sertraline", "None"]', 1, 'Must be tapered slowly. (First Aid)'),
    (v_topic_id, '340: A patient taking Clozapine develops excessive salivation (sialorrhea). What is the treatment?",', '["Stop Clozapine", "Clonidine or anticholinergic drops (e.g., Atropine)", "Give a beta-blocker", "None"]', 1, 'A common and bothersome side effect managed symptomatically. (MGH Pocket)'),
    (v_topic_id, '341: What is the mechanism of action of Pramipexole?",', '["Dopamine antagonist", "Dopamine Agonist", "Serotonin agonist", "None"]', 1, 'Used for Parkinson''s Disease and Restless Legs Syndrome. (Kaplan & Sadock)'),
    (v_topic_id, '342: A patient taking an SSRI and Sumatriptan develops agitation, clonus, and hyperreflexia. Diagnosis?",', '["NMS", "Serotonin Syndrome", "Anticholinergic toxicity", "None"]', 1, 'Both medications increase serotonergic activity. (First Aid)'),
    (v_topic_id, '343: Which medication is a partial mu-opioid agonist used for MAT and can be prescribed in an outpatient setting?",', '["Methadone", "Buprenorphine", "Naltrexone", "None"]', 1, 'Has a ceiling effect for respiratory depression. (MGH Pocket)'),
    (v_topic_id, '344: A patient taking Valproic Acid and Lamotrigine together is at increased risk for what?",', '["Liver failure", "Stevens-Johnson Syndrome (SJS)", "Kidney failure", "None"]', 1, 'Valproate inhibits the metabolism of Lamotrigine, doubling its levels. (Kaplan & Sadock)'),
    (v_topic_id, '345: Which atypical antipsychotic acts as a partial D2 agonist?",', '["Quetiapine", "Aripiprazole", "Olanzapine", "None"]', 1, 'Stabilizes dopamine transmission rather than fully blocking it. (First Aid)'),
    (v_topic_id, '346: A patient with narcolepsy is prescribed a non-amphetamine wakefulness-promoting agent. Which medication?",', '["Methylphenidate", "Modafinil", "Sodium Oxybate", "None"]', 1, 'First-line for narcolepsy and shift-work sleep disorder. (MGH Pocket)'),
    (v_topic_id, '347: What is the primary mechanism of action of Acamprosate in alcohol use disorder?",', '["Blocks alcohol absorption", "Modulates NMDA (glutamate) receptors", "Causes vomiting", "None"]', 1, 'Reduces the hyper-excitability of chronic withdrawal. (Kaplan & Sadock)'),
    (v_topic_id, '348: A patient taking Haloperidol constantly paces and cannot sit still. What is the treatment?",', '["More Haloperidol", "Propranolol (Beta-blocker)", "Lithium", "None"]', 1, 'First-line for Akathisia. (First Aid)'),
    (v_topic_id, '349: Which benzodiazepine is preferred in patients with severe liver cirrhosis?",', '["Diazepam", "Lorazepam", "Alprazolam", "None"]', 1, 'Lorazepam, Oxazepam, and Temazepam (LOT) bypass hepatic oxidation. (MGH Pocket)'),
    (v_topic_id, '350: A patient taking a typical antipsychotic develops severe, irreversible lip-smacking and tongue protrusion. Diagnosis?",', '["Acute dystonia", "Tardive Dyskinesia", "Akathisia", "None"]', 1, 'Caused by long-term D2 receptor upregulation. (Kaplan & Sadock)'),
    (v_topic_id, '351: What is the mechanism of action of Valbenazine?",', '["Dopamine agonist", "VMAT2 inhibitor", "Serotonin antagonist", "None"]', 1, 'FDA-approved treatment for Tardive Dyskinesia. (First Aid)'),
    (v_topic_id, '352: Which medication is an irreversible inhibitor of aldehyde dehydrogenase used for alcohol use disorder?",', '["Naltrexone", "Disulfiram", "Acamprosate", "None"]', 1, 'Aversive therapy; causes severe reaction if alcohol is consumed. (MGH Pocket)'),
    (v_topic_id, '353: A patient taking Lithium presents with a fine resting tremor. What is the management?",', '["Stop Lithium", "Prescribe a Beta-blocker (Propranolol)", "Give Haloperidol", "None"]', 1, 'A common side effect that does not require stopping the drug if levels are therapeutic. (Kaplan & Sadock)'),
    (v_topic_id, '354: Which atypical antipsychotic is most commonly associated with severe weight gain and metabolic syndrome?",', '["Aripiprazole", "Olanzapine", "Ziprasidone", "None"]', 1, 'Requires strict monitoring of weight, lipids, and A1c. (First Aid)'),
    (v_topic_id, '355: A patient with bipolar disorder is manic. Which of the following is NOT an appropriate monotherapy?",', '["Valproate", "Fluoxetine", "Lithium", "None"]', 1, 'Antidepressants can induce mania if used without a mood stabilizer. (MGH Pocket)'),
    (v_topic_id, '356: What is the primary mechanism of action of Duloxetine?",', '["SSRI", "SNRI", "TCA", "None"]', 1, 'Useful for depression with comorbid neuropathic pain. (Kaplan & Sadock)'),
    (v_topic_id, '357: A patient taking Clozapine develops a fever and chest pain. Troponins are elevated. Diagnosis?",', '["Panic attack", "Clozapine-induced Myocarditis", "Heartburn", "None"]', 1, 'A fatal complication requiring immediate cessation. (First Aid)'),
    (v_topic_id, '358: Which medication is a pure opioid antagonist used to reverse acute opioid overdose?",', '["Buprenorphine", "Naloxone", "Methadone", "None"]', 1, 'Works immediately to reverse respiratory depression. (MGH Pocket)'),
    (v_topic_id, '359: A patient taking an MAOI experiences a hypertensive crisis. What is the best treatment?",', '["Propranolol", "Phentolamine", "Epinephrine", "None"]', 1, 'Alpha-1 blockade is required to reverse the vasoconstriction. (Kaplan & Sadock)'),
    (v_topic_id, '360: What is the mechanism of action of Cyproheptadine in Serotonin Syndrome?",', '["Serotonin agonist", "5-HT2 receptor antagonist", "Dopamine antagonist", "None"]', 1, 'Directly blocks the excessive serotonergic stimulation. (First Aid)'),
    (v_topic_id, '361: Which class of medications is first-line for treating ADHD in children?",', '["SSRIs", "Stimulants (Amphetamines/Methylphenidate)", "Antipsychotics", "None"]', 1, 'Highly effective for core symptoms of ADHD. (MGH Pocket)'),
    (v_topic_id, '362: A patient taking Haloperidol develops a sudden, sustained, painful contraction of their neck muscles (torticollis). Diagnosis?",', '["Tardive Dyskinesia", "Acute Dystonia", "Akathisia", "None"]', 1, 'Treat with IM Benztropine or Diphenhydramine. (Kaplan & Sadock)'),
    (v_topic_id, '363: What is the primary mechanism of action of Memantine?",', '["Acetylcholinesterase inhibitor", "NMDA receptor antagonist", "Dopamine agonist", "None"]', 1, 'Used for moderate to severe Alzheimer''s disease. (First Aid)'),
    (v_topic_id, '364: Which SSRI is considered the safest to use during pregnancy and breastfeeding?",', '["Paroxetine", "Sertraline", "Fluoxetine", "None"]', 1, 'The go-to medication for perinatal depression. (MGH Pocket)'),
    (v_topic_id, '365: A patient taking Carbamazepine for bipolar disorder develops an absolute neutrophil count (ANC) of 500. Diagnosis?",', '["Viral URI", "Carbamazepine-induced Agranulocytosis", "Leukemia", "None"]', 1, 'A black box warning requiring immediate cessation. (Kaplan & Sadock)'),
    (v_topic_id, '366: What is the pharmacological treatment for TCA cardiotoxicity (widened QRS complex)?",', '["Amiodarone", "IV Sodium Bicarbonate", "Lidocaine", "None"]', 1, 'Overcomes the sodium channel blockade. (First Aid)'),
    (v_topic_id, '367: Which medication is an orexin receptor antagonist used for insomnia?",', '["Zolpidem", "Suvorexant", "Melatonin", "None"]', 1, 'Blocks the wake-promoting neuropeptide. (MGH Pocket)'),
    (v_topic_id, '368: A patient taking Lithium develops polyuria, polydipsia, and dilute urine. Diagnosis?",', '["Diabetes Mellitus", "Nephrogenic Diabetes Insipidus", "SIADH", "None"]', 1, 'Lithium desensitizes the collecting duct to ADH. (Kaplan & Sadock)'),
    (v_topic_id, '369: What is the primary mechanism of action of Ketamine?",', '["Serotonin reuptake inhibitor", "NMDA receptor antagonist", "Dopamine agonist", "None"]', 1, 'Used for rapid-acting treatment of severe depression. (First Aid)'),
    (v_topic_id, '370: Final Pearl: When treating a patient with bipolar disorder, what is the most critical rule regarding antidepressant use?",', '["Always use high doses", "NEVER use an antidepressant without a concurrent mood stabilizer, as it can precipitate severe mania or rapid cycling", "Only use SSRIs", "None"]', 1, 'A fundamental principle of bipolar management. (MediHelp Mastery)');
